pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins with smaller post_residual.
    // 2. Harmonic penalty: heavily penalize residuals that are too small to fit common items (10-30).
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // 3. Lookahead integration: 
    // If next_item_size fits in the current post_residual, prioritize this bin (negative reward).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Density balance:
    // Avoid creating too many bins. If we are early in the stream, favor filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is dynamic: higher when many bins are already open.
        score += (open_bins_count as f64 * 5.0) + (progress * 20.0);
    }

    // 5. Harmonic division threshold:
    // If post_residual is a multiple of common item sizes, it's potentially "cleaner".
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 6. Last chance logic:
    // If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Global mean alignment:
    // Penalize bins that deviate too far from the average residual space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit logic (lower post_residual is better)
    // We penalize high post_residual to encourage tight packing.
    let mut score = post.powf(1.5);

    // Dynamic Lookahead Penalty:
    // If the next item is large and the current post_residual is too small to accommodate it,
    // we penalize this bin to save space for the next step.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powf(1.2) * 5.0;
        }
    }

    // Stream Progress Adaptation:
    // As the stream progresses, become increasingly aggressive about closing bins (Best-Fit).
    // Early on, allow slightly more loose packing to maintain flexibility.
    let flexibility_penalty = (1.0 - progress) * 10.0;
    score += post * flexibility_penalty;

    // Fragmentation Avoidance:
    // Penalize placements that create "dead zones" (residuals smaller than the smallest possible item size, 
    // approximated here as 10).
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the score is very low
    // compared to the current average state of bins.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins; only justified if existing bins are highly fragmented.
        score = 25.0 + (mean_residual * 0.5);
    } else {
        // If this is the last fitting bin, slightly reward picking it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating 'slivers': space too small for the next expected item.
    // We penalize post_residual heavily if it's smaller than next_item_size, 
    // but only if a lookahead is available.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powi(2) * 0.5;
        }
    }

    // Dynamic pressure: As the stream progresses, favor tighter packing (lower residual).
    // We add a non-linear coupling between current residual state and progress.
    score += (mean_residual - post) * progress.powi(2) * 10.0;

    // Discourage opening new bins unless the fit is extremely poor.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, which decays as progress increases
        // (we accept new bins more easily toward the end to clear remaining items).
        score += 25.0 * (1.0 - progress.powi(2));

        // If there are other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage filling existing bins that are 'near empty' to balance the load.
        // Penalty proportional to how much space is left after placing the item.
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

