pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residual that cannot fit future items)
    // If post_residual is < 10, it is likely unusable for any incoming item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive Lookahead Matching
    // If next_item_size is known, favor bins where post_residual is closest to next_item_size
    // without going negative (Perfect Fit logic).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can perfectly accommodate the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Penalize bins that cannot fit the next item if they could have
            score += 20.0;
        }
    }

    // 3. Global Density Optimization
    // If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalty for opening a new bin is scaled by the progress of the stream
            let progress = step_index as f64 / total_items as f64;
            score += 80.0 * (1.0 - progress);
        }
    }

    // 4. Mean Residual Equilibrium
    // If the post_residual is significantly below the mean_residual, 
    // it suggests we are making this bin "tighter" than average, which is good.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Urgency Constraint
    // If this is the last chance bin (fitting_bins_count == 1), 
    // prioritize it to avoid creating unnecessary fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residual that cannot fit typical items)
    // We prioritize bins that result in a post-residual that is either 0 or large enough for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If next_item_size fits perfectly into the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Balance usage across bins: 
    // If this bin's residual is significantly lower than the mean, it's a "tight" bin. 
    // Penalize making tight bins tighter unless it's a perfect fit.
    if (bin_residual as f64) < mean_residual && post_residual > 0 {
        score += 15.0;
    }

    // 4. Threshold management: 
    // If only one bin can fit the item, we are forced to use it. 
    // If fitting_bins_count is 0, we are evaluating a new bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are already very full (mean_residual is low)
        // or if we have very few open bins.
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 40.0; 
        }
    } else {
        // If we have many fitting bins, be more selective (Best Fit variation)
        score += (fitting_bins_count as f64) * 2.0;
    }

    // 5. Progression scaling:
    // As we near the end of the stream, prioritize packing tighter (minimize new bins).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We favor bins where post_residual is as small as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the new post_residual,
    // reward this placement heavily to minimize future fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 2.0;
        } else {
            // Penalize if the current placement prevents the next item from fitting
            // in a bin where it otherwise might have fit.
            score += next_item_size as f64 * 0.8;
        }
    }

    // 3. New Bin Thresholding: Prevent opening a new bin unless the current fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the mean residual is already quite high,
        // suggesting that existing bins are poorly utilized.
        if mean_residual < 20.0 && open_bins_count > 0 {
            score += 200.0; // Heavy penalty for opening new bins prematurely
        } else {
            score -= 50.0; // Allow new bins if existing ones are fragmented
        }
    }

    // 4. Fitting Pressure: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 5. Progress Scaling: As we approach the end of the stream, prioritize 
    // closing open bins (using existing capacity) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We prioritize keeping residuals large enough to accommodate common harmonic chunks.
    if post_residual > 0 && post_residual < 20 {
        score += 50.0;
    }

    // Heuristic: If we are near the end of the stream, prioritize tightly packing remaining items.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 * 1.5);
    }

    // Harmonic class logic: Favor bins that leave residuals which are multiples of common item sizes (e.g., 25, 33, 50).
    // We reward residuals that align with the capacity fractions.
    let remainder_mod = (post_residual % 25) as f64;
    score += remainder_mod * 0.8;

    // If this is the only bin that fits the item, avoid opening a new one unless it's a perfect fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalty for opening a new bin if we have many open bins already (avoid fragmentation).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64 * 5.0);
    }

    // Reward bins that bring the bin residual closer to the mean residual of the system.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in the range [1, 9], it's likely to remain unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If next_item_size can fit into the new post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the tightest one (lowest post_residual).
    // If we have few open bins, prioritize keeping bins with larger residuals open for future large items.
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * 0.5;
    }

    // 4. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if the current mean_residual is very low (implying we are already packed tight).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; 
        } else {
            // Penalty for opening a new bin: proportional to existing fragmentation.
            score = 45.0 + (mean_residual * 0.5);
        }
    }

    // 5. Harmonic Class Logic: Prefer filling bins to specific "harmonic" thresholds (e.g., 50, 33, 25).
    // We reward post_residuals that are close to 0 (perfect fit) or close to bin_capacity/k.
    let harmonic_mod = post_residual % 25;
    if harmonic_mod < 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize empty bins increasingly as the stream progresses to favor consolidation
    let new_bin_penalty = 15.0 + (progress * 45.0);

    let score = if bin_residual == bin_capacity {
        // Scoring for a new bin: high penalty early, extreme penalty late
        new_bin_penalty
    } else {
        // Base score: prioritize tighter fits (smaller post_residual)
        let mut s = post;

        // Non-linear coupling: penalize residuals that are too small to fit the lookahead item
        // unless it's the very end of the stream
        if next_item_size > 0 && post < next_item_size as f64 && progress < 0.95 {
            s += (next_item_size as f64 - post) * 1.5;
        }

        // Coupling: If this is the only bin that can fit the item, reward it to prevent 
        // unnecessary new bin creation
        if fitting_bins_count == 1 {
            s -= 20.0;
        }

        // Deviation penalty: penalize bins that deviate significantly from the mean residual
        // to encourage uniform bin filling
        let deviation = (post - mean_residual).abs();
        s += deviation * 0.2;

        s
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits that leave little room.
    // However, if the post_residual is very small (e.g., < 5), it is often better to accept it 
    // to avoid creating 'dead' space that can't fit any future items (since min item size is likely > 5).
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0;
    }

    // 2. Lookahead Logic: If the next item fits in the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
    }

    // 3. Fragmentation Penalty: Avoid creating bins with mid-range residuals (e.g., 15-30) 
    // which are often too small for large items but too large to be considered "tight".
    if post_residual >= 15 && post_residual <= 35 {
        score += 20.0;
    }

    // 4. Harmonic Scaling: Penalize opening new bins unless the current options are all poor.
    // If this is a new bin (bin_residual == bin_capacity), set a high baseline cost.
    if bin_residual == bin_capacity {
        score += 65.0;
        // Reduce the new bin penalty if we have many open bins already (to encourage consolidation).
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. Scarcity Adjustment: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression Bias: As the stream progresses, favor tighter packing to close bins out.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 7. Mean Residual Alignment: Penalize bins that deviate significantly from the mean residual.
    // This keeps the remaining space across bins uniform, increasing the probability that 
    // future items will fit into one of the existing bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that likely won't fit future items)
    // We penalize residuals that are smaller than the smallest likely future items (approx 15-20)
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // 2. Harmonic Lookahead: If the next item can fit perfectly in this post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = (post_residual - next_item_size) as f64;
        // Reward tighter fits for the lookahead item
        score -= (100.0 - fit_margin) * 0.8;
    }

    // 3. Pressure management: If only one bin can fit this item, prioritize it to avoid opening a new bin
    // unless the current fit is catastrophic (post_residual < 5).
    if fitting_bins_count == 1 && post_residual > 5 {
        score -= 50.0;
    }

    // 4. Distributional balance: Penalize opening a new bin if the mean_residual of existing bins
    // suggests there is plenty of space elsewhere.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 150.0; // Discourage opening new bins prematurely
        }
        score += 20.0; // Base cost to open a new bin
    }

    // 5. Modulo-based capacity alignment: Prefer residuals that are multiples of 10
    // to keep bins "compatible" with common item sizes (often round numbers).
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // 6. Progression scaling: As the stream nears the end, be more aggressive about filling existing bins
    // to minimize the tail-end bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" option heavily early on, but allow it if it's the only way to avoid fragmentation.
    // If bin_residual == bin_capacity, we are evaluating the choice of opening a fresh bin.
    let is_new_bin = bin_residual == bin_capacity;

    // Base heuristic: Best-Fit (minimizing post_residual)
    // We add a non-linear penalty for small post_residuals (fragmentation) that increases as the stream progresses.
    // A small post_residual (e.g., 1-5) is often "dead space" that cannot fit future items.
    let fragmentation_penalty = if post < 10.0 {
        (10.0 - post).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead logic: if we know the next item, penalize bins that cannot fit it
    // if we put the current item in this bin.
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 {
