        }
    }

    // Weighting the open bin count: avoid creating too many bins if we have space elsewhere.
    let bin_density_bias = (open_bins_count as f64 * 0.5) * (1.0 - progress);

    let mut score = post + fragmentation_penalty + lookahead_penalty + bin_density_bias;

    // Adjust the "New Bin" cost:
    // If we have many fitting bins, opening a new one should be very expensive.
    if is_new_bin {
        // If we are forced to open a new bin (no other fits), this score will be compared to others.
        // We set the baseline cost of a new bin to be high.
        score = 45.0 + (progress * 20.0);

        // If there are other bins that could fit the item, penalize the new bin decision even more.
        if fitting_bins_count > 0 {
