    // Smaller post_residual is better (lower score).

    // 2. Lookahead Penalty:
    // If the next item cannot fit into the post_residual, we penalize this placement.
    // This discourages creating "dead space" that cannot accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
