    // 3. Global Packing Efficiency:
    // If we have many open bins, we want to prioritize filling bins closer to the mean,
    // to avoid creating fragmented space across too many bins.
    if open_bins_count > 1 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold.
    // Only open a new bin if the current "best" existing fit is poor (post_residual > 30).
    if bin_residual == bin_capacity {
