    // If post_residual is small (e.g., < 10), it's often a good fit, but if it's 
    // a "sliver" (e.g., 1-9), it might be hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead logic: if next item is large, avoid leaving a residual that 
    // makes it impossible to fit the next item in this bin.
    if next_item_size > 0 && post_residual < next_item_size {
