        // the current mean_residual is very low (meaning we are packing tightly).
        // If fitting_bins_count is high, we have options, so don't open a new one.
        score += 35.0; 
        score -= (open_bins_count as f64) * 0.5;
        score -= (mean_residual * 0.2);
    } else {
        // Reward using existing bins, especially if they are already "partially full"
        // (i.e., bin_residual is low).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Dynamic time horizon: As we approach the end of the stream, prioritize 
    // fitting into existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= 10.0;
    }

    score
}

