        }
    } else {
        // Encourage balanced filling of existing bins.
        // If the current bin's post_residual is significantly better than 
        // the global mean_residual, reward it.
        if post < mean_residual {
            score -= (mean_residual - post).sqrt() * 5.0;
        }
    }

    score
}

