pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the "wasted" space in the bin after placement.
    // We aim to minimize this while considering lookahead and bin density.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is < 10 (the minimum item size), it is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If the next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for keeping space for the next item.
            score -= 30.0;
        } else {
            // Penalty if we cannot fit the next item in this bin, 
            // only if the bin was already partially filled.
            if bin_residual < bin_capacity {
                score += 15.0;
            }
        }
    }

    // 3. Global state: If we have many open bins, penalize opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Higher penalty for opening a new bin if we have many fitting options.
        score += (open_bins_count as f64) * 2.5;

        // Dynamic thresholding: as the stream progresses, make it harder to open new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Density heuristic: Favor bins that stay close to the current mean residual.
    // This keeps the "fill level" uniform across bins, increasing future packing flexibility.
    let deviation = (post_residual as f64 - (mean_residual - item_size as f64)).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating a new bin: only open when necessary or when late-stage
    // allows for more aggressive packing.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already (high fragmentation)
        // or if we are nearing the end of the stream where consolidation is less critical.
        score += 25.0 * (1.0 - progress) + (open_bins_count as f64 * 0.5);
    } else {
        // Favor bins that align with the next item size (lookahead coupling)
        if next_item_size > 0 {
            let gap_penalty = (post_res - next_item_size as f64).abs();
            score += gap_penalty * 0.8;
        }

        // Quadratic penalty for creating "dead space" that is too small for common items
        // as the stream progresses, we become more tolerant of larger residuals.
        let dead_space_factor = 1.0 - (post_res / bin_capacity as f64);
        score += (post_res.powf(1.5)) * (1.0 - (progress * dead_space_factor));

        // If this is the last fitting bin, prioritize it to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Adjust for global fragmentation: if mean_residual is high, we are already wasting space,
    // so prioritize tighter fits even more aggressively.
    score += (mean_residual - post_res) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: prioritize filling bins to specific "harmonic" thresholds (e.g., 1/2, 1/3, 1/4 of capacity)
    // to leave room for future items.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals that are too small to fit typical items).
    // Small residuals are only good if they are near 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Alignment: Reward residuals that are multiples of 25 (1/4 capacity) or 33 (1/3).
    // This creates "slots" for future items.
    let harmonic_penalty = (post_residual % 25) as f64 + (post_residual % 33) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead integration: If the next item is large, favor larger residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize if the bin won't fit the next item when it could have
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
