    // 5. New Bin Logic: Discourage opening a new bin unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high; only take it if existing bins are very cluttered.
        score = 45.0 + (open_bins_count as f64 * 2.0) - (mean_residual * 0.1);
