    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as progress approaches 1.0
    // to force packing efficiency in the later stages of the stream.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + (progress * 50.0).powf(1.5));

