    // If next_item_size is 0 (end of stream), we prioritize filling bins completely.
    let lookahead_val = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    let fit_efficiency = (post_res - lookahead_val).abs();

    // Interaction: Penalize thin residuals that are too small to fit common items (10-20 range),
    // unless we are nearing the end of the stream (progress -> 1.0).
    let fragmentation_penalty = if post_res < 15.0 && post_res > 0.0 {
        (15.0 - post_res) * (1.0 - progress) * 2.0
    } else {
