    let desperation_bonus = if fitting_bins_count == 1 && is_new_bin == 0.0 { -100.0 } else { 0.0 };

    let score = post_res 
        + new_bin_penalty 
        + fit_efficiency 
        + fragmentation_penalty 
        + mean_deviation 
        + desperation_bonus;

    score
}

