        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open bins pressure: As we progress, we want to consolidate items. 
    // Penalize opening new bins when current open bins are underutilized.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize heavily if we have plenty of open bins (open_bins_count).
        score += (open_bins_count as f64) * 15.0;

        // If we are nearing the end of the stream, prioritize closing bins over opening new ones.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // 3. Fitting preference: Reward bins that become "tighter" (lower post_residual).
        // This is a Best-Fit variant.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Lookahead awareness: If the next item is large, avoid leaving small residuals 
    // that won't accommodate it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // 5. Consolidate: If only one bin fits, prioritize it strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
