    // 3. Density Balancing: Prefer bins closer to the global mean residual to keep bin levels uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the current options are "bad" (e.g., leaving fragmented space).
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if the fitting options are poor.
        score += 35.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If we are placing in an existing bin, favor those that leave the bin "tight".
        // This is the Best-Fit Decreasing intuition expressed via post_residual.
        score += (post_residual as f64) * 0.1;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
