    // as we approach the end of the stream to consolidate leftovers.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + 20.0
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: penalize larger post-residuals (wasted space)
    // but modulate by the remaining capacity of other bins to avoid starving them.
    let waste_penalty = post * 1.5;

    // Lookahead interaction: If the next item is large, prioritize keeping 
