pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit logic)
    let mut score = post;

    // Penalty for creating "dead space" (very small residuals)
    // Small residuals are hard to fill later, especially as the stream progresses.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 5.0);
    }

    // Lookahead: if the next item is large, penalize bins that cannot accommodate it
    // after the current placement.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.5;
        }
    }

    // Dynamic thresholding: as the stream approaches the end, be more aggressive
    // about fitting items into existing bins to avoid opening new ones.
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    // Penalty for opening new bins: if this is a new bin, add a heavy cost
    // that decays slightly as we run out of total items (desperation factor).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - (progress * 0.5));
    }

    // Interaction with mean_residual: favor bins that bring the bin closer to the
    // global mean residual to maintain uniformity.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // Small fragments (1-9) are usually "dead space" that cannot fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Compatibility: If the next item fits into the current post_residual,
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it fills the bin almost perfectly
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the existing options are very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean residual is already quite low (high utilization)
        // or if we have very few fitting options.
        score += 35.0;
        if mean_residual < 20.0 {
            score += 20.0;
        }
    }

    // 4. Harmonic Alignment: Reward residuals that align with common item sizes (multiples of 10).
    // This keeps the bins "clean" for future items in the stream.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin && progress > 0.8 {
        score += 30.0;
    }

    // 6. Crowding penalty: If many bins are open, try to pack into existing ones to keep open_bins_count low.
    if !is_new_bin {
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the residual space after placement.
    // We aim to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is small but > 0, it's often unusable.
    // Penalize gaps that are too small to fit the smallest expected items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Open bins pressure: As the stream progresses, favor packing into existing bins
    // to keep the bin count low. Penalize opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead optimization: If the next item is large, avoid leaving a residual
    // that is too small for it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 4. Fitting bin count awareness: If this is the only bin that can fit the item,
    // reduce the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 5. Global state normalization: Penalize bins that deviate far from the mean residual,
    // encouraging a uniform distribution of fill levels across bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

