        score += 45.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Lookahead logic: If a future item exists, prioritize bins that can accommodate it later
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else {
            score += 10.0; // Penalize bins that will definitely not fit the next item
        }
    }

    // 3. Global State: Discourage opening new bins early in the process unless necessary
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // High penalty for opening a new bin if we have existing capacity
            score += 60.0 * (1.0 - progress);
        }
    } else {
        // 4. Fitting Density: If this is the only bin that fits, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // 5. Mean residual balancing: Prefer bins that stay close to the mean to keep packing uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
