    // 3. Incorporate the lookahead (next_item_size) to favor leaving space for large upcoming items.
    // 4. Use progress to become more aggressive at closing bins as the stream nears the end.

    let mut score = post.powf(1.5);

    // Penalty for creating "slivers" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
