    // Harmonic preference: Favor residuals that are multiples of 20 (100/5)
    // This helps keep bins modular for standard item sizes.
    let remainder = post_residual % 20;
    score += remainder as f64 * 0.8;

    // Strategy for opening new bins:
    // Only open a new bin if the current fit is extremely poor (post_residual < 15)
