pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size fits in post_residual, reward the bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. New bin penalty: Exponentially increase cost of opening new bins as the process nears completion
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
        // Penalty for opening a new bin if we have plenty of open bins
        score += (open_bins_count as f64) * 2.0;
    } else {
        // 4. Tightness reward: Favor bins that become "tight" (residual < 10)
        if post_residual < 10 {
            score -= 30.0;
        }
        // 5. Global state: If the current bin is significantly better than the mean, prioritize it
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 6. Last-chance logic: If this is the only bin that fits, heavily favor it to avoid new bin creation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // 7. Mid-stream adjustment: Prevent fragmenting bins early on
    if progress < 0.3 && post_residual > 50 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // We add a penalty for empty bins to prevent premature opening.
    let mut score = post_res * post_res;

    // Interaction 1: Penalize leaving small, unusable gaps (1-9) as the stream progresses.
    // This creates a "dead space" penalty that grows as the bin packing nears completion.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 50.0 * (1.0 + progress);
    }

    // Interaction 2: Lookahead coupling.
    // If the next item is large, penalize small residuals that would force a new bin later.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post_res < next_item && post_res > 0.0 {
            score += (next_item - post_res) * 20.0;
        }
    }

    // Interaction 3: Dynamic bin density management.
    // Discourage opening a new bin if we have many open bins already.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // Increase the cost of opening a new bin as we reach the end of the stream
        // to encourage consolidating into existing bins.
        score += progress * 100.0;
    }

    // Interaction 4: Use mean_residual to balance the load.
    // Prefer bins that are closer to the current average residual to keep bin levels uniform.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post-residuals that are small but non-zero (fragments)
    // We prefer post_residuals that are close to 0 (perfect fit) or larger than the next_item_size.
    if post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 2. Bin Thresholding: If this is the last chance for the current item, 
    // heavily penalize the "New Bin" option unless the residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 3. Modulo Alignment: Favor residuals that are multiples of 10, as they are 
    // more likely to accommodate common item size distributions.
    if post_residual % 10 != 0 {
        score += 2.5;
    }

    // 4. Mean Residual Balancing: If the bin's post-residual is significantly 
    // below the global mean, we are creating a "tight" bin.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Progression Weighting: As we approach the end of the stream, 
    // prioritize packing tighter (minimize residual) over future flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    // 6. Avoid fragmented space: Penalize bins that leave very small slivers (1-5)
    if post_residual > 0 && post_residual < 6 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit typical future items.
    // If a gap is between 1 and 9, it's effectively "dead space" as items start at 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when current ones are available.
    // Discourage new bins unless the fit is extremely tight (Best Fit).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 4. Fitting Density: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Mean Alignment: If current bin residual is far above mean, it's a "wasteful" bin.
    // Penalize using bins that are significantly emptier than the average open bin.
    if bin_residual as f64 > mean_residual + 15.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (too small for most items)
    // Residuals < 10 are dangerous as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead matching: reward if post_residual fits the next item exactly
    // This is the core "Best-Fit-Lookahead" logic.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // Penalize if the next item won't fit here
            score += 5.0;
        }
    }

    // 3. Dynamic thresholding based on stream progression
    // As the stream nears completion, become more aggressive in packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 4. Prefer bins that keep the mean_residual stable
    // High mean_residual means bins are mostly empty; try to fill those first.
    if (bin_residual as f64) > mean_residual {
        score -= 15.0;
    }

    // 5. New bin logic:
    // Only open a new bin if the current fit is extremely poor (post_residual < 20)
    // or if fitting_bins_count is low and we want to preserve better bins for future items.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening a new bin prematurely
            score = 80.0 + (mean_residual * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
