    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is small (e.g., < 10), it's often a waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
