    }

    // 3. Global state: If we are nearing the end of the stream, prioritize packing tighter
    // to avoid leaving too many bins partially filled.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: strongly prefer filling existing bins over opening new ones.
        if bin_residual == bin_capacity {
            score += 50.0;
        }
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // prioritize it to avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Balance: Favor bins that stay close to the current mean residual to keep 
    // distribution uniform across active bins, reducing variance.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. New bin penalty: Make opening a new bin expensive unless necessary.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow flexibility as the stream ends.
    // We aim to minimize post_residual (Best Fit), but penalize fragments that are too small 
    // to fit future items (dead space).
    let mut score = post_residual as f64;

    // Penalty for creating a bin with a very small residual that likely won't fit future items.
    // If post_residual is < 10, it's likely "dead space" unless the stream is nearly finished.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 - progress).powf(2.0) * 10.0;
    }

    // Lookahead logic: if the next item is large and the current bin will be too small,
    // penalize this placement to keep larger bins available for larger items.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Heuristic for new bin:
    if is_new_bin {
        // Only open a new bin if we have many bins open already (to avoid fragmentation)
        // or if the current options are all very poor fits.
        // Base penalty for opening a new bin is high.
        score = 60.0 + (progress * 20.0);

        // If we have very few bins open, discourage opening a new one.
        if open_bins_count < 3 {
            score += 40.0;
        }
    } else {
        // Reward bins that have residuals close to the mean, promoting balanced bin usage.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

