    // We prioritize keeping residuals that are multiples of common item sizes or large enough for future items.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 45.0; // Severe penalty: sliver of space is usually wasted
        } else if post_residual < next_item_size && next_item_size > 0 {
            score += 30.0; // Penalty: cannot fit the immediate next item
        }
    }

    // Harmonic alignment: Favor residuals that are perfect fits or leave room for common modular sizes
    let harmonic_fit = (bin_capacity - post_residual) % 25;
    score -= (harmonic_fit as f64) * 0.5;

    // If this is the only bin that fits the item, make it highly attractive to prevent opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current mean_residual is already very tight (< 15)
    // or if the current item is very large (> 70) and would fragment a bin poorly.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 && item_size < 75 {
            score += 500.0; // Heavily penalize opening a new bin unnecessarily
        } else {
            score -= 10.0; // Slight bias toward keeping bins somewhat balanced
        }
    }

    // Lookahead influence: if next_item_size is large, prioritize bins that can accommodate it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
