    // We heavily penalize small "unusable" gaps (1-9) where future items are unlikely to fit.
    // We penalize opening new bins unless the current options are very poor.

    let mut score = post_residual as f64;

    // 1. Penalize small unusable gaps (1-9) which are "dead space" traps.
    if post_residual > 0 && post_residual < 10 {
