    // 5. Progression weighting: As we approach the end of the stream, 
    // prioritize clearing existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We favor smaller post_residuals (the standard Best-Fit behavior).

    // 2. Lookahead Synergy: If the remaining space can accommodate the next item, 
    // heavily reward this bin to keep the next item from forcing a new bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further refine: reward bins where the resulting residual after the next item 
        // would be minimal (Perfect-Fit lookahead).
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. New Bin Thresholding: 
    // If the bin is new, penalize based on the current mean_residual of existing bins.
    // If our current bins are already quite empty, don't open a new one.
    if bin_residual == bin_capacity {
        score += mean_residual * 1.5;
        // Penalize opening a new bin if we have many fitting bins already.
        score += (fitting_bins_count as f64) * 10.0;
    }

    // 4. Fragmentation Penalty:
    // If post_residual is small but not zero (e.g., 1-9), it often creates 'dead space' 
    // that no future item can fill. Penalize these "bad" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Progression Weighting:
    // As we approach the end of the stream, be more aggressive about filling existing 
    // bins to avoid leaving stragglers.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

