        // Global state awareness: If we have many open bins, penalize creating more 'loose' bins.
        // If post_residual is small (e.g., < 10), it's a "dead" bin; reward it as it's nearly full.
        if post_residual < 10 {
            score -= 20.0;
        }

        // Adaptive threshold: If we are late in the stream, be more aggressive about filling bins
        // even if it leaves slightly more residual space.
        if progress > 0.8 && post_residual < 20 {
            score -= 10.0;
        }

        // Penalize bins that deviate significantly from the current mean residual
        // to encourage uniform bin usage.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating 'slivers': space too small for the next expected item.
    // We penalize post_residual heavily if it's smaller than next_item_size, 
    // but only if a lookahead is available.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powi(2) * 0.5;
        }
    }

    // Dynamic pressure: As the stream progresses, favor tighter packing (lower residual).
    // We add a non-linear coupling between current residual state and progress.
    score += (mean_residual - post) * progress.powi(2) * 10.0;

    // Discourage opening new bins unless the fit is extremely poor.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, which decays as progress increases
        // (we accept new bins more easily toward the end to clear remaining items).
        score += 25.0 * (1.0 - progress.powi(2));

        // If there are other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage filling existing bins that are 'near empty' to balance the load.
        // Penalty proportional to how much space is left after placing the item.
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small for common items (e.g., < 10)
    // but rewards tight fits that leave exactly 0 space.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
