    // Heuristic: If we are in the early stages, favor filling bins to capacity.
    // If we are late in the stream, favor keeping bins open to accommodate remaining items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (open_bins_count as f64);

    // Lookahead logic: if the next item can fit in the current post_residual, 
    // reward this placement to chain items together.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it's a perfect fit for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Harmonic logic: Penalize bins that leave residuals which don't fit common 
    // fractions of the capacity, favoring "clean" bin states.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 10.0;
    }

    // If this is the only bin that can fit the item, prioritize it heavily 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New bin candidate handling:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only want to open this if the score is significantly lower than existing options.
    if bin_residual == bin_capacity {
        score += 45.0; // Base cost to open a new bin
        // Adjust cost based on how many bins are already open
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
