        score += 5.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Tightness reward: Favor bins that are near-full (Best-Fit principle).
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, be more aggressive 
    // about packing into existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
