    // Objectives: 
    // 1. Minimize residual space (Best Fit).
    // 2. Penalize "fragmentation" (small residuals that cannot accommodate future items).
    // 3. Use lookahead to avoid creating "orphaned" bins.

    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too small for common item ranges
    // If post_residual is small but > 0, it creates "dead space" (fragmentation).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0; 
    }

    // Harmonic influence: Reward filling bins to specific thresholds (e.g., 80, 90, 100)
    // This aligns with bin packing patterns where packing large items is prioritized.
    let fill_level = bin_capacity - post_residual;
    if fill_level > 85 {
        score -= 15.0; // Strong reward for high-density packing
    }

    // Lookahead logic (k=2):
    // If we have a next item, penalize current placements that prevent the next item 
    // from fitting into the same bin, effectively encouraging "Best Fit" for pairs.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // Reward pairs that fit into the same bin
        }
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // proportional to the number of existing bins to discourage sprawl.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64 * 0.5);
    }

    // Penalize if the bin is the last chance for the current item
    // but the resulting post_residual is poor.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 5.0;
    }

    // Progression scaling: As we reach the end of the stream, prioritize 
    // packing tighter (reducing total_bins).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit common items
    // (1..10) are the "danger zone" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary
    // If it's a new bin, penalize based on current open bin count to prevent fragmentation
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Sensitivity: If the next item is large, prioritize keeping space available
    if next_item_size > 50 && post_residual < next_item_size {
        score += 20.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Residual Balancing: Reward bins that stay near the mean to prevent outlier bins
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items)
    // Residuals < 10 are often unusable given the item range (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead matching: reward bins that can perfectly or nearly accommodate the next item.
    if next_item_size > 0 {
        let gap = post_residual as i32 - next_item_size as i32;
        if gap >= 0 {
            // Reward exact fit (gap 0) or tight fit (gap < 5)
            score -= (100.0 / (gap as f64 + 1.0));
        } else {
            // Penalize if the next item won't fit in this bin anymore
            score += 20.0;
        }
    }

    // 3. Balance usage: If fitting_bins_count is 1, we are at the limit for this item.
    // Avoid opening a new bin unless the fit is truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have existing options
            score += 60.0;
        } else {
            // If no other options, normalize the new bin cost
            score = 40.0;
        }
    } else {
        // 4. Prefer bins that keep the mean residual tight.
        // If post_residual is much lower than the mean, we are packing efficiently.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 5. Progress scaling: As we approach the end, be more conservative with new bin openings.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
