    // We favor bins that leave the least space (Best Fit).
    score += (post_residual as f64).powf(1.5);

    // 2. Penalty for wasting space on a new bin (if fitting_bins_count > 0)
    // If we have an empty bin (bin_residual == bin_capacity) but others fit, penalize it.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0 * (1.0 - progress);
    }

    // 3. Lookahead integration: Try to avoid creating "dead space" for the next item
    // If the next item is large, we want a bin that can accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize if this placement blocks the next item from fitting
            score += 50.0;
        } else {
            // Reward if this placement leaves room for the next item (synergy)
            score -= 30.0;
        }
    }

    // 4. Global state optimization: Balance the load across bins
    // If the mean residual is high, we are under-utilizing bins; try to consolidate.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Dynamic threshold for opening new bins
    // As we near the end of the stream, prioritize closing bins over opening new ones.
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize large gaps that are likely to become stranded ("dead space").
    let mut score = post_res * post_res;

    // Favor bins that have a residual close to the next item's size (Lookahead optimization).
    if next_item_size > 0 {
        let diff = (post_res - next_item_size as f64).abs();
        score -= (100.0 - diff) * 0.5;
    }

    // Dynamic pressure: As the stream progresses, become more conservative about 
    // opening new bins (penalize new bins) and more aggressive about filling existing ones.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, scaling with progress to force consolidation.
        score += 500.0 * (1.0 + progress);
    } else {
        // Reward bins that maintain a residual close to the global mean, 
        // promoting uniform packing density.
        let mean_diff = (post_res - mean_residual).abs();
        score += mean_diff * 2.0;
    }

    // Criticality logic: If this is the last fitting bin, prioritize it strongly
    // to avoid unnecessary fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize bins that create very small, unusable slivers (< 5 units) 
    // unless it results in a perfect fit (0 residual).
    if post_residual > 0 && post_residual < 5 {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Harmonic-weighted Best-Fit with Lookahead Pressure
    // We aim to minimize the post_residual, but heavily penalize "useless" small gaps
    // that cannot accommodate the next_item_size.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too small for common item sizes (harmonic thresholding)
    // If post_residual is small but > 0, it is often a "dead" space.
    if !is_new_bin && post_residual > 0 {
        // Penalize gaps that are smaller than the average expected item size (heuristically 25)
        if post_residual < 25 {
            score += 15.0 * (25.0 - post_residual as f64);
        }

        // Lookahead synergy: if the next item can fit in the post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // New bin management:
    // Only open a new bin if the current fitting options are extremely poor (high post_residual)
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong discouragement for opening new bins if alternatives exist
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, we must open one, but normalize the score to be competitive
            score = 50.0;
        }
    }

    // Harmonic packing: prioritize filling bins that are already closer to capacity
    // to keep the number of active bins low.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Progressive tightening: as we approach the end of the stream, prioritize tighter fits
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
