pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // We want the post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 2.0;

    // 2. Lookahead mechanism: If next_item_size fits in the post_residual, 
    // heavily reward this bin to keep it tightly packed.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
        // Further reward if the resulting gap after the next item is minimal
        score -= (post_residual - next_item_size) as f64 * 1.5;
    }

    // 3. Penalty for opening new bins unnecessarily
    // If this is a brand-new bin (residual == capacity), penalize it 
    // unless no existing bins can fit the item or the mean residual is already very high.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong disincentive to open new bins
        }
        // If we must open a new bin, prioritize those that leave a balanced residual
        score += mean_residual * 0.5;
    }

    // 4. Critical thresholding: If this is the last fitting bin, prioritize it 
    // to avoid the "new bin" penalty triggered by the logic above.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // prioritize filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // post_residual: 0 is perfect (Best Fit).
    // Large post_residual: Bad (wasted space).
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely.
    // If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already that are "cluttered"
