        }
    }

    // 3. Global state: Avoid creating many bins with very small residuals (unusable space).
    // If post_residual is small (e.g., < 10), it is often "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // 4. Balance: If we have many open bins, try to consolidate by favoring bins 
    // that are already quite full (low mean_residual).
    if open_bins_count > 5 {
        score += mean_residual * 0.1;
    }

    // 5. Urgency: If this is the last chance for this item, reduce penalty for poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We penalize high post_residual (wasted space) but adjust based on context.
    let mut score = post;

    // Penalty for creating "slivers" (small, unusable residuals)
    // We penalize residuals that are too small to fit the next item or common small items.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic: If the next item won't fit in the remaining space, 
    // we increase the score (penalize) to encourage finding a bin that keeps 
    // the current bin useful for the next item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 20.0 * (1.0 - progress);
    }

    // Reward bins that bring the residual closer to the global mean (tight packing)
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.5;

    // Favor opening a new bin only if the current fit is extremely poor (large post_residual)
    // and we are early in the stream.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate score.
        // We make it attractive only if current open bins are very full 
        // or if we are late in the stream to avoid fragmentation.
        score = 45.0 + (progress * 10.0);
    } else {
        // If it's a fitting bin, apply a discount based on how many other 
        // options exist. If it's the only option, we are forced to take it.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Polynomial coupling: Penalize large residuals more harshly as the stream progresses
    // to force tighter packing towards the end.
    score += (post * post) / (bin_capacity as f64) * progress;

    score
}

