        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Balance against average occupancy: If this bin's residual is significantly worse 
    // than the mean_residual, penalize it to encourage uniform packing.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize new bin creation heavily, but soften as we approach the end of the stream
    // to allow for better packing density in the final stages.
    if is_new_bin {
        score += (bin_capacity as f64) * (1.5 - progress);

        // If there are other bins that can fit the item, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Non-linear coupling: Reward placements that leave very little space,
        // but penalize creating "orphaned" space (e.g., < 10 units) if the 
        // next item is large.
        if post_residual > 0 && post_residual < 10 {
            if next_item_size > post_residual {
                score += (10.0 - post_residual as f64) * 2.5;
