        }

        // Favor bins that are already closer to the mean density to keep bins uniform
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Lookahead logic: If the next item is large, prioritize bins that keep 
    // the current residual high enough to accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic:
    // Penalize residuals that cannot easily accommodate common item sizes (10, 20, 25, 33, 50).
    // We favor residuals that are multiples of common divisors.
    let harmonic_penalty = if post_residual > 0 {
        let factors = [10.0, 20.0, 25.0, 50.0];
        let mut min_dist = 100.0;
        for &f in &factors {
            let dist = (post_residual as f64 % f).min(f - (post_residual as f64 % f));
            if dist < min_dist { min_dist = dist; }
        }
        min_dist * 2.0
    } else {
        0.0
    };
    score += harmonic_penalty;

    // 3. Lookahead Logic:
    // If next_item_size fits in the post_residual, drastically reduce score (reward).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 150.0;
        // Further reward if it fills the bin almost perfectly
        if (post_residual - next_item_size) < 10 {
            score -= 50.0;
        }
    }

    // 4. Open-Bin Management:
    // Avoid opening new bins unless necessary (fitting_bins_count > 0).
    // If it's a new bin (bin_residual == bin_capacity), penalize it based on how many
    // other bins could have taken the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0 + (fitting_bins_count as f64 * 50.0);
        }
    }

    // 5. Global density adjustment:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize leaving small gaps that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize post_residual 
    // that is smaller than the next item if we have other bins available.
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 25.0;
    }

    // 3. Global Bin Pressure: Penalize opening new bins when many are already open.
