    // 4. Efficiency Bias: Reward filling a bin almost completely (Best Fit variant).
    // A post_residual of 0 is the most desirable state.
    if post_residual == 0 {
        score -= 10.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize 
    // closing bins (low residuals) over keeping many partially filled bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 150.0;
        }
        return score;
    }

    // 2. Penalty for creating "fragmented" space (small unusable residuals)
    // We penalize residuals that are too small to fit the average minimum item (approx 10)
    // but large enough to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 3. 2-step Lookahead: Reward if the post_residual can perfectly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward "tightness" relative to the next item
            score -= (20.0 * (next_item_size as f64 / (post_residual as f64 + 1.0)));
        } else {
            // Penalty if the next item cannot fit in this bin anymore
            score += 25.0;
        }
    }

    // 4. Global state awareness: Reward using bins that are already "fuller" than the mean
    // to keep the spread of residuals low (Best-Fit principle)
    if (bin_capacity - bin_residual) as f64 > (bin_capacity as f64 - mean_residual) {
        score -= 15.0;
    }

    // 5. Critical constraint: If this is the only bin that fits, we must prioritize it
    // unless the fit is extremely poor (handled by the new-bin penalty above)
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (waste)
    // We want post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: 
    // If the next item fits into the current post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Penalty for opening new bins:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost 
    // unless fitting_bins_count is 0 (we are forced to open a new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 - progress * 0.5);
        }
    } else {
        // 4. Global state coupling: 
        // Penalize bins that deviate significantly from the mean_residual of all bins.
        // This encourages "leveling" the residuals to keep options open.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 5. Critical Thresholding:
    // If this is the last chance for this item (fitting_bins_count == 1),
    // reward fitting it here to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
