    // We scale the penalty by the current mean_residual to avoid fragmentation.
    if is_new_bin {
        let new_bin_penalty = 15.0 + (progress * 40.0) + (mean_residual * 0.5);
        score += new_bin_penalty;
    } else {
        // Lookahead optimization:
        // If the next item is large and fits into this current bin's post_residual,
        // we heavily reward placing the current item here to save the space for the next one.
        if next_item_size > 0 && next_item_size <= post_residual {
