        if post_residual > 0 && post_residual < 5 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Favor bins that have a smaller residual than the global mean to consolidate space
    if !is_new_bin && (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    }

    // If this is the last chance for the current item, reduce the penalty significantly
    // to ensure we don't force a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

