    }

    // 4. Harmonic Modulo Logic: Penalize residuals that are not multiples of common bin-fillers (e.g., 20, 25).
    // This encourages bins to reach "clean" capacity states.
    let remainder = post_residual % 20;
    if remainder != 0 {
        score += remainder as f64 * 0.5;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the current best fit is objectively poor.
    if bin_residual == bin_capacity {
        // If we have fitting bins, opening a new one is expensive unless all fits are "bad" (> 30 residual).
        if fitting_bins_count > 0 {
            score += 35.0 + (mean_residual * 0.5);
        } else {
            score -= 5.0; // Accept opening a new bin if nothing else fits.
        }
    }

    // 6. Dynamic Scaling: As the stream progresses, become more conservative about wasting space.
    score += (progress * 10.0);

