    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize residual space (standard Best-Fit logic)
    // We favor smaller post_residuals.

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin to maximize bin utilization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current
    // fitting options are extremely poor (i.e., very large post_residuals).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced as we approach the end of the stream
        // to ensure we don't leave many half-empty bins at the end.
        score += 35.0 * (1.0 - progress);

        // If there are other bins that could have fit the item, strongly discourage new bin
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Global State Balancing: If current mean residual is high, we are being too wasteful.
    // Discourage placements that increase the mean residual further.
    if (post_residual as f64) > mean_residual {
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 5. Scarcity Handling: If this is the only bin that can fit the item,
    // make it highly attractive to preserve the bin for future items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Dynamic Scaling: Penalize deep fragmentation (small residuals < 10)
    // unless it perfectly fills the bin (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    } else if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

