        score += 45.0; // Base cost of opening a new bin
        // Reduce penalty if current open bins are already very full (high mean_residual)
        score -= mean_residual * 0.3;
    }

    // 4. Scarcity/Bottleneck Logic:
    // If this is the last bin that can fit the item, give it a significant boost
    // to prevent unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression Scaling:
    // As the stream nears completion, become more aggressive about filling existing bins
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
