    // Strategy shift: As we near the end of the stream, prioritize aggressive packing (lower residuals)
    // Early in the stream, favor keeping bins balanced (higher mean_residual)
    let balance_pressure = (post - mean_residual).powi(2) * (1.0 - progress);

    // If this is a new bin, apply a dynamic cost that increases as we approach the end of the stream
    // to discourage opening new bins when space is tight.
    let new_bin_cost = if bin_residual == bin_capacity {
