    // 2. Lookahead matching: reward bins where the post_residual is close to the next_item_size.
    // This minimizes fragmentation by creating "perfect fits" for the upcoming item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // Penalize if the post_residual is too small to fit the next item when it could have fit elsewhere
        if post_residual < next_item_size && fitting_bins_count > 1 {
            score += 50.0;
        }
    }

    // 3. Efficiency heuristic: Penalize creating bins that are far from the current mean_residual.
    // This encourages "clustering" bin usage to specific residual levels.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.3;

    // 4. Tightness bias: Favor bins that become very full (Best-Fit principle).
    // The lower the post_residual, the better, but protect against creating unusable slivers (e.g., < 5).
    if post_residual > 0 && post_residual < 5 {
        score += 30.0; // Penalty for creating "dead zones"
    } else if post_residual == 0 {
        score -= 10.0; // Strong reward for perfect fills
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
