    // We increase the score if post_residual is between 1 and 9 (too small for most items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Lookahead: If next_item_size can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Modulo-Alignment: If the post_residual is a multiple of next_item_size, it's a "clean" fit.
    if next_item_size > 5 && post_residual % next_item_size == 0 {
        score -= 15.0;
    }

    // 4. Global Density Control: If fitting_bins_count is 1, we are forced to use this bin.
    // If it's a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing one can fit the item.
            score += 60.0;
        } else {
            // Must open a new bin, normalize score.
            score = 10.0;
        }
    }

    // 5. Mean residual variance: If this bin's residual deviates significantly from the mean,
    // discourage using it to keep bin states consolidated.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.1;

    // 6. Progression factor: As we approach the end of the stream, prioritize tightest packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
