    if is_new_bin {
        // Only open a new bin if the current fit options are extremely poor (High post_residual)
        // or if we are nearing the end of the stream and need to clear out remaining items.
        let openness_threshold = 25.0 + (progress * 25.0);
        score = openness_threshold;

        // If no existing bin can fit the item, we must open a new one.
        if fitting_bins_count == 0 {
            score = -100.0; 
        }
    } else {
        // If this bin is the *only* one that can fit the item, prioritize it heavily
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Penalize bins that are too empty, favoring those that are already becoming full.
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items.
    // We penalize values below 10 specifically, scaled by the remaining capacity.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead influence: If the next item doesn't fit in the remaining space, 
    // we should prioritize bins that leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: As we approach the end of the stream, prioritize 
    // packing density (minimizing open_bins_count) over individual bin residuals.
    let density_pressure = open_bins_count as f64 * progress;
    score += density_pressure * (post_res / bin_capacity as f64);

    // If this is the last fitting bin, we provide a slight discount to encourage 
    // closing it, effectively acting as a "force-fit" mechanism to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalty for opening a new bin:
    // If the bin is brand new (residual == capacity), we apply a high cost that 
    // decays as the stream progresses, forcing efficient packing early on 
    // and allowing new bins only when necessary later.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
