        score += 5.0; 
    }

    // 4. Distribution Balancing:
    // If we are late in the stream, be more aggressive about filling bins (lowering score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 5. New Bin Logic:
    // A new bin is represented by bin_residual == bin_capacity.
    // We penalize opening a new bin unless the existing options are very poor.
    if bin_residual == bin_capacity {
        score += 35.0; // Threshold to force filling existing bins first
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
