        } else {
            // Penalty if next item cannot fit in current bin's remaining space
            score += 10.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that are outliers compared to current mean
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Urgency: As we approach the end of the stream, prioritize space density over lookahead
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
