        score -= 40.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when many are already open,
    // unless the current fit is exceptionally good.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 2.5;
    } else {
