        }
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // 5. Progression Scaling: As we reach the end of the stream, 
    // become more aggressive about minimizing total open bins.
    let progress = step_index as f64 / total_items as f64;
