    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item exists, penalize bins that 
    // cannot accommodate it if this bin is currently the only fitting option.
    if next_item_size > 0 && fitting_bins_count == 1 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 3. Global Density Balancing: If we have many open bins, prioritize 
    // filling bins with low residuals to consolidate space.
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 4. New Bin Thresholding: Discourage opening new bins early in the stream, 
    // but allow flexibility as the stream approaches completion.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is 35.0. 
        // We reduce this cost as we near the end of the stream to reduce fragmentation.
        score = 35.0 - (progress * 15.0);

        // If we have many open bins, make it harder to open a new one.
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Reward tight packing: If the item fills the bin exactly, prioritize this bin heavily.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

