    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often worse than having 0 residual.
    if post > 0.0 && post < 15.0 {
        score += 20.0 * (1.0 - (post / 15.0));
    }

    // Lookahead logic: if we know the next item, prioritize bins that fit it
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - progress);
        } else {
            score += 10.0 * progress;
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, 
    // become more aggressive in packing to minimize new bin creation.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - progress);
    }

    // Normalize against mean_residual to prevent massive fragmentation
    // If this bin is significantly worse than the current average, penalize it
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    // New bin candidate logic: 
    // If bin_residual == bin_capacity, this is a new bin.
    // We only want to open it if existing bins are poor fits (high post_residual)
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, reduced by progress (late game desperation)
        score = 60.0 - (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a sliver that is hard to fill (e.g., 1-9 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic preference: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This helps pack items of similar size together.
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit * 0.5;

    // Lookahead logic: If the next item can fit perfectly or near-perfectly into the current post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let space_left_after_next = (post_residual - next_item_size) as f64;
            // Reward placements that leave room for the next item, heavily penalize if it leaves an unusable sliver
            if space_left_after_next < 10.0 && space_left_after_next > 0.0 {
                score += 40.0;
            } else {
                score -= 15.0;
            }
        }
    }

    // Dynamic pressure: If fitting_bins_count is low, we are running out of options.
    // Prefer packing tightly in the current bin if it's the only one that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New bin handling: Only open a new bin if the mean residual is high, 
    // implying existing bins are already too fragmented to be useful.
    if bin_residual == bin_capacity {
        if mean_residual > 30.0 || open_bins_count == 0 {
            score += 10.0;
        } else {
            score += 100.0; // Heavily penalize opening new bins if current bins are healthy
        }
    }

    // Progression scaling: As we near the end of the stream, prioritize filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
