        score += 85.0 * (1.0 - progress * 0.5);
    } else {
        // Reward bins that stay close to the mean residual to maintain uniform availability.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // 5. Final adjustment: Strongly discourage "Best Fit" if it leaves a sliver, 
    // preferring "Worst Fit" for large items to keep small gaps for small items.
    if item_size > 60 && post_residual > 20 {
        score -= 15.0;
    }

    score
