        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Dynamic pressure: as we approach the end of the stream, prioritize closing bins (lower mean_residual).
    // We favor bins that bring the mean_residual closer to the ideal (low) state.
    let residual_improvement = (mean_residual - post) * progress;
    score += residual_improvement;

    // Penalize opening a new bin (where bin_residual == bin_capacity) 
    // unless the fit in existing bins is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for new bins early in the stream, decreasing as we near the end.
        score += (1.0 - progress) * 45.0;

        // If we are forced to open a bin because all others are bad fits, 
        // the penalty is mitigated by the poor fit quality of alternatives.
        score += (open_bins_count as f64 * 2.0);
    }

    // Favor bins that maintain a high fitting_bins_count to keep options open, 
    // but penalize if it's the absolute last chance (fitting_bins_count == 1).
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // Core logic: Best Fit Decreasing (BFD) strategy modified by lookahead and residual fragmentation.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common item sizes).
    // Residuals < 10 are often useless given the item range [10, 80].
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic coupling: Favor bins that leave room for the next item.
    // If the next item can fit in the post_residual, drastically reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin is a good fit.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many bins open or if no bins can fit the item well.
        score += 35.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 15.0;
        }
    }

    // 4. Mean Residual Equilibrium:
    // Avoid creating bins that are significantly "emptier" than the average open bin.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, be more conservative with bin openings.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance with bin-count pressure.
    // 1. Base Score: The post_residual is the primary metric.
    let mut score = post_residual as f64;

    // 2. Dead Space Penalty: Penalize small gaps (1..9) that are likely to become stranded.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Bin Pressure: Penalize opening new bins when space is available elsewhere.
    // If this is a new bin (residual == capacity), penalize it based on open_bins_count
    // to encourage packing into existing bins unless they are highly fragmented.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Fragmentation Awareness: If a bin is the last chance for this item (fitting_bins_count == 1),
    // and it results in a very small residual, heavily penalize it to force the use of other bins
    // if possible, or prefer a new bin if the current bin is "poisoned".
    if fitting_bins_count == 1 && post_residual < 5 {
        score += 30.0;
    }

    // 6. Progressive Consolidation: As the stream nears completion, favor tighter packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

