    // 3. Mean Residual Balancing: Avoid creating bins that are outliers compared to the average.
    // If we are currently creating a "straggler" bin (residual significantly higher than mean), penalize it.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 4. Tightness bias: Prefer filling bins to capacity (Best Fit principle).
