}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (small residual space that is hard to fill)
    // We penalize values below 10 (common lower bound of item sizes) exponentially
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powf(2.5);
    }

    // Dynamic Lookahead coupling:
    // If the next item is large, favor bins that can accommodate it.
    // If next_item_size is 0, we are at the end of the stream; prioritize compacting.
    if next_item_size > 0 {
        let fit_margin = post_residual as i32 - next_item_size as i32;
        if fit_margin < 0 {
            // Penalize bins that will be unable to fit the lookahead item
            score += (next_item_size as f64 * 0.5) * (1.0 + progress);
        }
    }

    // Global state optimization:
    // As the stream progresses, increase the cost of opening new bins (is_new_bin)
    // to encourage consolidation.
    if is_new_bin {
        score += 25.0 * (1.0 + progress.powf(1.5));

        // If there are other bins that could have fit this, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Reward bins that keep the mean residual balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

