    // 2. Lookahead: Harmonic coupling with the next item
    // If the current placement leaves a gap that perfectly fits the next item, 
    // we drastically lower the score.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact matches or near-exact matches
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 / (1.0 + diff)) + (20.0 / (1.0 + (post_residual % next_item_size) as f64));
        } else {
            // If next item cannot fit, we penalize the current placement if it makes 
            // the bin "unusable" for the future.
            score += 15.0;
        }
    }

    // 3. Harmonic class logic: Favor bins that align with common capacity fractions
    // (e.g., leaving 50, 33, or 25 space is often better for future packing)
    let remainder_score = match post_residual {
        r if r % 25 == 0 => -10.0,
        r if r % 20 == 0 => -8.0,
        _ => 0.0,
    };
    score += remainder_score;

    // 4. Global pressure: If we are near the end of the stream, prioritize 
    // packing density over bin count efficiency.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 5. New Bin Logic:
    // If the bin is new, only pick it if the score is very low (high penalty for opening).
    if bin_residual == bin_capacity {
        // High constant penalty for opening a new bin
        score += 45.0;

        // If many bins are already open and have room, discourage opening a new one
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
