pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We apply a heavy penalty to new bins unless the existing fit quality is abysmal.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Best-Fit logic: 
    // Prefer bins where the post_residual is small (tight packing).
    // The base score already includes post_residual, so we emphasize it.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead Matching (The "2-step" core):
    // If the next item fits perfectly into the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // Strong reward for a "near-perfect" match for the next item.
        score -= (100.0 - gap as f64) * 0.4;
    }

    // 4. Mean Residual balancing:
    // Penalize bins that deviate significantly from the average state of open bins.
    // This prevents creating "outlier" bins that are hard to fill later.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. Urgency factor:
    // If fitting_bins_count is 1, this is the only bin that can take this item.
    // We should reduce the score to encourage taking the fit before forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression scaling:
    // As the stream nears completion, become more aggressive about minimizing total bins
    // by tightening the constraints on opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We already start with post_residual.

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // reward this placement heavily to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Thresholding: 
    // If the bin is new, impose a penalty that decays as the stream progresses.
    // This forces "Best Fit" early on and "First Fit" or "New Bin" later if needed.
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 40.0;
        // Also penalize opening a new bin if other bins could have taken the item.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // 4. Global State Balancing:
    // If we have many open bins, we want to prioritize filling the one with the 
    // smallest residual to close it out (Best Fit).
    // If the current bin's residual is significantly smaller than the mean, 
    // it's a good target.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Fragmentation Avoidance:
    // If the post_residual is small but > 0, it's often wasted space (dead space).
    // If it's 0, it's a perfect fit.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        score += 15.0 + (progress * 45.0);
    } else {
        // Reward bins that are "tighter" relative to the mean residual of current open bins.
        // This encourages leveling the load across bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;

        // Lookahead heuristic: If the next item exists, penalize placements that leave 
        // a post_residual that is too small to accommodate the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }

        // If this is the last fitting bin, prioritize it to avoid opening a new one,
        // unless the post_residual is exceptionally small (dead space).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Non-linear coupling: penalize very small post_residuals (dead space) 
    // more heavily as the stream nears completion.
    if !is_new_bin && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 + progress * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "dead space" (post_residual) while favoring bins that align 
    // with harmonic classes (e.g., 20, 25, 33, 50).
    // Penalize small residuals that are likely to become stranded ("orphans").

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Harmonic Class Penalty:
    // If post_residual is small (e.g., < 10), it's often a "dead" zone. 
    // We penalize these unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Coupling:
    // If the next item is large, we want a bin that can accommodate it.
    // If post_residual is less than next_item_size, we penalize this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 3. Global Density Balancing:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have fitting options.
        let new_bin_penalty = 30.0 + (progress * 20.0);
        score += new_bin_penalty;
    }

    // 4. Fitting Pressure:
    // If this is the last bin that can fit the item, we lower the score to ensure we don't 
    // waste a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Mean Residual Alignment:
    // Favor bins that stay near the global mean residual to maintain uniform bin usage.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is too small for any likely item (10-80),
    // heavily penalize it to force tighter packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // reward this bin to encourage "pairing" items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, discourage opening new ones 
    // unless the fit is exceptionally good.
    if bin_residual < bin_capacity {
