        score -= 20.0;
    }

    // 5. Prefer bins that keep the mean residual of the system balanced.
    // We want to avoid bins that are much emptier than the current mean.
    let residual_delta = (bin_residual as f64) - mean_residual;
    if residual_delta > 0.0 {
        score += residual_delta * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

