    // 2. Dead-space avoidance: Penalize residuals that are too small to fit any possible item (e.g., < 10)
    // but large enough to waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 3. New Bin Management: Only open a new bin if the current mean_residual is already tight,
