            score += 10.0;
        } else {
            // Otherwise, strongly discourage opening a new bin
            score += 200.0;
        }
    }

    // 4. Lookahead awareness: If this is the last chance for this bin (fitting_bins_count == 1),
    // and the post_residual is poor, penalize it to force a new bin.
    if fitting_bins_count == 1 && post_residual > 30 {
        score += 30.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
