    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead Coupling: If next_item_size fits in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress);
    }

    // 3. Global State: If we are near the end of the stream, prioritize closing bins (lower residual)
    // even if it creates small gaps, to reduce total bin count.
    if progress > 0.85 {
