    // We penalize the 'new bin' option (bin_residual == bin_capacity) increasingly 
    // as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 40.0);

        // If there are other bins that can fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
