    // 4. Global Density Balance: Compare current bin residual to the global mean.
    // We want to keep residuals somewhat uniform to avoid outlier bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. New Bin Threshold: Discourage opening a new bin unless the fit is truly poor.
    // If we are considering a new bin, bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
