    // We only want to do this if all current fitting bins would result in poor fits.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to or if the average fit is very poor
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening new bins to encourage filling existing ones
            // Unless the mean_residual of existing bins is already very small
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // If this is the only bin that fits, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow it more as the stream progresses
    // to avoid fragmenting early bins.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 15.0 * (1.0 - progress) } else { 0.0 };

    // Best-fit principle: minimize post_residual, but weigh it against the 
    // probability that the remaining space is too small for future items.
    // We use a non-linear penalty for small residuals that are "dead space" (e.g., < 10).
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powf(1.5)
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size is large and fits in current post_residual, 
    // prioritize this bin to prepare for the next step.
    let lookahead_bonus = if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        -12.0 * (next_item_size as f64 / bin_capacity as f64)
    } else {
        0.0
    };

    // Global state coupling: If we have many bins open, try to pack tighter 
    // into existing ones rather than opening new ones.
    let density_pressure = (open_bins_count as f64) * 0.5;

    // Final score assembly
    // Lower is better. New bins start with high penalty, existing ones are ranked by 
    // their post_residual with a quadratic penalty for near-empty "dead" gaps.
    let mut score = post + dead_space_penalty + new_bin_penalty + lookahead_bonus + density_pressure;

    // If this is the last chance to fit the item in an open bin (fitting_bins_count == 1),
    // reduce score to ensure we don't open a new bin unnecessarily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // 2. Penalty for creating "dead space": if post_residual is in (0, 10), 
    //    it's highly likely to be wasted. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If current post_residual is too small to fit next_item_size, we penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 4. Threshold for opening new bins: 
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // Only open a new bin if the current mean_residual is very low (implying existing bins are tight)
    // or if we have very few open bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Force opening first bin
        } else if mean_residual < 15.0 {
            score = 10.0; // Moderate preference to open new bin if existing ones are crowded
        } else {
            score = 200.0; // Heavy penalty to prevent unnecessary bin opening
        }
    }

    // 5. Harmonic refinement: Use modulo to penalize "awkward" residuals that 
    // don't divide the capacity well, favoring bins that leave "clean" room (multiples of 20).
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 6. Final scaling based on progression: 
    // As we approach the end of the stream, be more conservative with bin opening.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
