    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is a candidate for a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (no other options) 
        // or if our current open bins are already very full.
        // We penalize the new bin by the mean residual of existing bins.
        score += mean_residual * (1.0 + progress);

        // If we have plenty of open bins, discourage opening another.
        score += (open_bins_count as f64).powf(1.5);
    } else {
        // For existing bins, favor placements that leave a residual 
