        if next_item_size > 0 {
            let fitness_gap = post - (next_item_size as f64);
            if fitness_gap >= 0.0 {
                // Reward bins that can fit the next item perfectly.
                score -= (100.0 - fitness_gap).sqrt() * 2.0;
            } else {
