    };

    score += residual_penalty + lookahead_score + density_pressure + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that create unusable gaps (1..9).
    // These gaps are too small for any item (min size 10), effectively wasting capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the 
    // current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 40.0;
        } else if gap_after_next >= 10 {
            score -= 15.0;
        }
    }

    // 3. Open Bins Pressure: If fitting_bins_count is 1, we are at a decision bottleneck.
    // Discourage opening a new bin unless the post_residual is extremely efficient.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // Encourage filling existing bins to keep open_bins_count low.
        score -= (1.0 / (fitting_bins_count as f64 + 0.1)) * 10.0;
    }

    // 4. Density Balancing: Favor bins that stay near the mean residual to prevent 
    // fragmented capacity across the bin set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progress weighting: In the final stages of the stream, prioritize aggressive 
    // packing (lower post_residual) to close out bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // We only open a new bin if the score is lower than existing bins.
    // We heavily penalize new bins based on current fill state to force packing into existing ones.
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 2. Lookahead matching:
    // If the next item fits perfectly into this post_residual, reward this placement.
    // This is the core "Best Fit" logic enhanced by lookahead.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Penalize small slivers that are too small for the next item but leave space wasted.
            score += 5.0;
        } else {
            // If post_residual is too small for the next item, add a mild penalty.
            score += 2.0;
