    }

    // 3. Efficiency heuristic:
    // Favor bins that end up with very little residual (tight packing).
    // Penalize bins that leave a "dead zone" (e.g., 1-9) which is unlikely to fit future items.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; 
    }

    // 4. Density Balancing:
    // If we have many open bins, prioritize clearing the ones with the lowest residual 
    // to keep open_bins_count low.
    if open_bins_count > 5 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Urgency:
    // As the stream progresses, increase pressure to pack tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
