            score += 50.0 * (1.0 - progress);
        }

        // 5. Global state balancing: If this bin's residual is significantly better than the mean, 
        // encourage filling it.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 6. Tighten constraints as the stream nears completion
    if progress > 0.95 {
