        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // We use a quadratic penalty for large residuals to favor Best-Fit behavior.
    let mut score = post_res * post_res / bin_capacity as f64;

    // Penalty for opening a new bin:
    // Only apply if the bin is empty (new bin candidate).
    if bin_residual == bin_capacity {
        // As the stream progresses, we become more conservative about opening new bins.
        // We scale the penalty by the number of open bins to discourage fragmentation.
        score += (bin_capacity as f64 * 0.4) + (open_bins_count as f64 * 5.0) * (1.0 + progress);
    } else {
        // Lookahead heuristic:
        // If the next item exists, penalize placements that leave a residual smaller than the next item,
        // as this creates "dead space" that cannot be filled by the immediate successor.
        if next_item_size > 0 {
            if post_res < next_item_size as f64 {
