            }
        }

        // Global efficiency correction:
        // If the current bin's residual is significantly lower than the mean residual,
        // it is a "tight" bin. We reward placing items here to consolidate space.
        if post_res < mean_residual {
            score -= (mean_residual - post_res) * 0.8;
        }
    }

    // Fitting constraint:
    // If this is the only bin that can fit the item, strongly incentivize choosing it 
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
