    let mut score = post_res;

    // Penalty for creating a 'sliver' (unusable space < 10, since min item size is 10).
    // We apply this non-linearly to emphasize avoiding the 1-9 range.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead logic: If the next item can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding based on stream progress:
    // As we near the end of the stream, we become increasingly aggressive about
    // consolidating into existing bins to minimize the total count.
    let consolidation_pressure = progress * 20.0;
    score += (open_bins_count as f64) * consolidation_pressure;

    // Penalize opening a new bin (bin_residual == bin_capacity) 
    // unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
        // Reduce penalty if this is the only option left
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Non-linear coupling: Reward bins where the resulting residual is close to the 
    // mean residual of all open bins (encourages uniform filling).
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that likely won't fit future items)
    // We penalize residuals that are smaller than the smallest likely future items (approx 15-20)
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // 2. Harmonic Lookahead: If the next item can fit perfectly in this post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = (post_residual - next_item_size) as f64;
        // Reward tighter fits for the lookahead item
        score -= (100.0 - fit_margin) * 0.8;
    }

    // 3. Pressure management: If only one bin can fit this item, prioritize it to avoid opening a new bin
    // unless the current fit is catastrophic (post_residual < 5).
    if fitting_bins_count == 1 && post_residual > 5 {
        score -= 50.0;
    }

    // 4. Distributional balance: Penalize opening a new bin if the mean_residual of existing bins
    // suggests there is plenty of space elsewhere.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 150.0; // Discourage opening new bins prematurely
        }
        score += 20.0; // Base cost to open a new bin
    }

    // 5. Modulo-based capacity alignment: Prefer residuals that are multiples of 10
    // to keep bins "compatible" with common item sizes (often round numbers).
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // 6. Progression scaling: As the stream nears the end, be more aggressive about filling existing bins
    // to minimize the tail-end bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Strict Best-Fit with a dynamic penalty for leaving "dead" space.
    // A gap is "dead" if it is smaller than the smallest likely item (approx 10-15).
    // We penalize post_residual values in the range [1, 14] heavily.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is in (0, 15), it's likely wasted.
    if post_residual > 0 && post_residual < 15 {
        score += 50.0 + (15.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If we have a next_item, prioritize bins that can fit it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Open bin pressure: Penalize opening a new bin if we have many open bins.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 10.0;

        // If we have other bins that can fit this, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Global efficiency: Favor bins that stay close to the mean residual of the set.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small to fit common items)
    // If post_residual is small but > 0, it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead matching: reward bins that leave exactly enough space for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that keep the residual close to the mean to maintain consolidation
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        } else {
            // Penalize if the next item won't fit in this bin anymore
            score += 15.0;
        }
    }

    // 3. Prefer filling bins that are already "tight" (Best Fit logic)
    // If the bin is new, apply a heavy penalty to discourage opening new bins prematurely
    if bin_residual == bin_capacity {
        score += 60.0;
        // If this is the only bin that fits the current item, reduce the penalty
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // 4. Density normalization based on progression
    // As we approach the end of the stream, prioritize closing bins over opening new ones
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We aim for Best-Fit Decreasing behavior while penalizing "fragmentation traps" 
    // where small residuals make future items impossible to place.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead zones": residuals too small for any item (assuming 10 is min item size)
    // If the post_residual is in (0, 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item cannot fit in this bin, penalize the choice
    // unless the current post_residual is already very small (tight fit).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 25.0 * (1.0 - progress); 
    }

    // 3. Global state balance: If we have many open bins, prioritize filling the ones 
    // that are already quite empty to reduce the count of active bins.
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 4. New bin threshold: If this is a new bin (residual == capacity), 
    // only pick it if the penalty of forcing a bad fit into existing bins is too high.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many fitting options that would result in 
        // very poor fragmentation (small post_residual).
        score += 45.0 - (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, reward it based on how well it matches the current item.
        // We prefer bins that result in a post_residual close to the mean_residual 
        // to keep the bin distribution uniform.
        score -= (100.0 - (post_residual as f64 - mean_residual).abs()) * 0.1;
    }

    // 5. Urgency: If this is the only fitting bin, accept it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the residual space after placement (Best Fit principle).
    // We want to minimize post_residual to pack bins tightly.
    let mut score = post;

    // Penalty for opening a new bin:
    // If bin_residual == capacity, we are evaluating a brand new bin.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // Higher progress makes opening a new bin more expensive.
        score += (capacity * 0.75) * (1.0 + progress);
    }

    // Lookahead logic:
    // If the next item is large, we want to save space in the current bin.
    // If the next item is small, we are less concerned with the current post_residual.
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64) / capacity;
        // If post_residual is too small to accommodate the next item, we penalize it 
        // to encourage picking a bin that leaves enough room for the lookahead.
        if (post_residual as u32) < next_item_size {
            score += lookahead_pressure * 25.0;
        }
    }

    // Interaction with mean_residual:
    // Penalize bins that deviate significantly from the mean residual of open bins
    // to keep the packing density consistent across all open bins.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // Fitting bins constraint:
    // If this is the ONLY bin that can fit the item, we should favor it heavily 
    // unless we are at the very beginning of the stream where efficiency matters less.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a heavy penalty based on current efficiency
    // to discourage opening new bins unless necessary.
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64 * 2.0) - (mean_residual * 0.5);
    } else {
        // 2. Harmonic Class Logic: Reward placements that leave remainders 
        // that are multiples of common item sizes (e.g., 20, 25, 33).
        // This promotes "perfect fit" clustering.
        let harmonic_penalty = (post_residual % 20) as f64;
        score += harmonic_penalty * 1.5;

