    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit typical future items (e.g., < 10)
    // but not exactly 0 (which is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight (Best Fit behavior).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Optimization: If the next item exists, penalize residuals that make it impossible
    // to fit the next item when it could have fit in a different bin configuration.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, prioritize it highly
    // to avoid unnecessary fragmentation or new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current bin is significantly worse than the mean residual of open bins,
    // penalize it to encourage packing items into "denser" bins first.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit (minimize post_residual)
    // The base score is already post_residual, which heavily favors tight fits.

    // 2. Penalty for opening a new bin if an existing bin could fit the item.
    // If we are evaluating the "new bin" candidate (bin_residual == bin_capacity)
    // and there are other bins that could fit the item, add a massive penalty.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 3. Lookahead Matching (The "Aggressive Match" logic)
    // If the next item fits perfectly into the remaining space (post_residual), 
    // we reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations where the next item fits almost exactly
        score -= (100.0 - diff) * 1.5;
    }

    // 4. Fragment Avoidance
    // Penalize small, unusable residuals (e.g., < 10) unless they are 0.
    // A residual of 1-9 is often a "dead space" trap.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 5. Global Load Balancing
    // If this bin's post_residual is significantly lower than the mean_residual of 
    // all open bins, it suggests this bin is becoming "fuller than average".
    // We want to encourage filling already-full bins to keep others empty.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Progressive Tightening
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
