        // Favor bins that bring the residual closer to the mean to maintain balance.
        score += (post_residual as f64 - mean_residual).abs() * 0.1;
    }

    // 4. Critical thresholding: If this is the last chance for this item (fitting_bins_count == 1),
    // heavily incentivize picking this existing bin over starting a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
