    // 3. Density Balancing: If we have many open bins, prioritize filling the most empty ones (Best Fit).
    // If we have few open bins, favor the tightest fit (First Fit / Worst Fit hybrid).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if open_bins_count > 5 {
        score += fill_ratio * 10.0;
    } else {
        score -= fill_ratio * 5.0;
    }

    // 4. Thresholding: Avoid opening a new bin unless the current residual is extremely poor.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to discourage fragmentation.
        score += 35.0;

        // If there are other bins that could fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Progress adjustment: As the stream nears the end, prioritize closing bins (minimizing residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
