    // but allow it if the current fit is extremely inefficient.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate "Tightness": reward placements that leave very little space,
    // but penalize creating "dead zones" (residuals too small for future items).
    // If post_residual is < 10 (smallest possible item size), it's likely dead space.
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Incorporate lookahead: if the next item is large, 
    // we want to preserve space in bins that can accommodate it.
    let lookahead_pressure = if next_item_size > 0 {
        let fits_next = (post as u32 >= next_item_size) as i32 as f64;
        (1.0 - fits_next) * (next_item_size as f64 * 0.5)
    } else {
        0.0
    };

    // Base score: prioritize smaller residuals (Best Fit behavior),
    // modulated by non-linear coupling with stream progress.
    let base_score = post * (1.0 + 0.5 * progress);

    base_score + new_bin_penalty + dead_space_penalty + lookahead_pressure
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post-residuals to keep bins tightly packed.
    // However, we reward "perfect fits" (post_residual == 0) heavily.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Harmonic Class logic: Identify "dead space" thresholds.
    // If post_residual is small but > 0, it's often better to leave it than create a new bin.
    // Penalize small slivers (e.g., 1-5) that likely won't fit future items.
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    // 3. Lookahead integration: If the next item is large, prioritize keeping space available.
    // If post_residual is smaller than the next item, we penalize this placement.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // 4. Strategic New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if current fits are "bad".
    // "Bad" is defined as mean_residual being significantly smaller than the item_size.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && (mean_residual as u32) > item_size {
            score += 20.0; // Discourage new bin if existing bins are spacious
        } else {
            score -= 5.0;  // Encourage new bin if existing bins are tight
        }
    }

    // 5. Scarcity/Density bonus:
    // If we are late in the stream, be more aggressive about closing bins (lower score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 6. Last chance logic:
    // If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit typical items (< 10)
    // but large enough to waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing capacity is sufficient.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless fitting_bins_count is 0 (forced).
    if bin_residual == bin_capacity {
