            score += 150.0 + (open_bins_count as f64 * 5.0);
        } else {
            score -= 20.0; // Base cost for opening a necessary new bin
        }
    }

    // 4. Compactness Bias: Prefer bins that stay close to the mean residual of the pack.
    // This reduces variance in bin fullness.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Progression Scaling: As we approach the end of the stream, prioritize finishing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
