pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin early in the stream, but allow it if it's the only option.
    // The penalty decreases as we approach the end of the stream to favor consolidation.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (1.0 - progress) * 50.0 + 10.0
    } else {
        0.0
    };

    // Use a non-linear penalty for small residuals (the "fragmentation" trap).
    // If post_residual is small but > 0, it creates "dead space" that is hard to fill.
    // We penalize based on the size of the remaining gap, weighted by the next item's potential fit.
    let fragmentation_penalty = if post_residual > 0 && post_residual < 15 {
        (15.0 - post) * 2.5
    } else {
        0.0
    };

    // Incorporate the lookahead: if next_item_size fits in the post_residual, 
    // provide a bonus (negative score) to prioritize this placement.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Favor bins that are already "tight" (low mean_residual) to keep others empty.
    let consolidation_pressure = (mean_residual - post) * 0.5;

    // Final score: minimize this value.
    // Base score is the post_residual itself (Best Fit logic).
    let score = post 
        + new_bin_penalty 
        + fragmentation_penalty 
        + lookahead_bonus 
        + consolidation_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
