        if fitting_bins_count > 0 && item_size < (bin_capacity as f64 - mean_residual) as u32 {
            score += 50.0; // Heavily penalize opening a new bin if a good fit exists.
        } else {
            score -= 10.0; // Mild incentive to open a new bin if the current fit is poor.
        }
    } else {
        // If this bin is the last one that can fit the item, reward it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 4. Progression Weighting:
    // As we approach the end of the stream, be more aggressive about filling existing bins (minimize new bins).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // post_residual represents space left after placing.
    // A lower post_residual (closer to 0) is generally better (Best Fit).

    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space that is too small for common items.
    // If post_residual is small but not zero (e.g., 1-9), it is often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Incorporate lookahead: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Dynamic weight based on stream progress: 
    // Near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we near the end of the stream
        score += 40.0 + (progress * 60.0);
    }

    // 4. Global state adjustment:
    // If we have many bins open, try to pack tighter into existing ones.
    // If fitting_bins_count is 1, this is the only bin that can take this item. 
    // Reward finishing this bin to keep the count of open bins low.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 20.0;
    }

    // 5. Penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill levels across all open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space: we prefer bins that are tightly packed.
    let mut score = post;

    // Penalty for creating a bin that is almost empty (fragmentation)
    // We penalize high post_residual proportionally to progress.
    // Near the end of the stream, we are more desperate to fit items, so we relax the penalty.
    let fragmentation_penalty = (post * post) / (bin_capacity as f64) * (1.0 - progress);
    score += fragmentation_penalty;

    // Lookahead coupling: if the next item is large, favor bins that leave enough space for it.
    // If post < next_item_size, we penalize the bin because it won't be able to fit the next item.
    if next_item_size > 0 {
        let lookahead_mismatch = (next_item_size as f64 - post).max(0.0);
        score += lookahead_mismatch * 0.5;
    }

    // Adaptive thresholding: if this is the only bin that fits the item, 
    // we want to reward it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // If we are considering a new bin (bin_residual == bin_capacity), 
    // heavily penalize it unless the current open bins are very poorly suited (high mean_residual).
    if bin_residual == bin_capacity {
        score += 40.0 + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmented' space (small, unusable residuals)
    // We penalize residuals that are smaller than the smallest likely item (10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Harmonic Class Logic: Reward placements that leave residuals that are multiples 
    // of common item sizes or leave the bin 'balanced' (near the mean residual)
    if !is_new_bin {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // Lookahead logic: If a future item exists, prioritize bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for accommodating the next item
        } else if post_residual > 0 {
            score += 10.0; // Penalty for blocking the next item
        }
    }

    // Threshold management: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we heavily discourage opening a new bin by inflating the new bin score.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 50.0 + (progress * 30.0);
        } else {
            // If no other bin fits, this is the only option, normalize score
            score -= 10.0;
        }
    }

    // Scale by open bin count to prevent excessive bin proliferation
    score += (open_bins_count as f64).powf(1.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
