    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean Residual Alignment: Favor bins that stay close to the average residual to maintain balance.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
