    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: If this is an existing bin (not a new one), 
    // penalize opening new bins by making existing ones more attractive.
    if bin_residual < bin_capacity {
        score -= 10.0;
    }

    // 4. Scarcity Constraint: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Mean residual equilibrium: Penalize bins that deviate significantly 
    // from the mean residual of open bins to encourage uniform bin filling.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Progress Scaling: As the stream nears completion, become more 
    // aggressive about closing bins (minimizing total_items).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but prioritize tight fits for the next_item_size.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only open a new bin if the current fit quality is poor across all bins
        // or if we have very few open bins (avoiding fragmentation).
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 2. Lookahead matching: reward bins that leave exactly enough space for the next item
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward tight fit for next item (Best-Fit-Lookahead)
        score -= (100.0 - diff) * 0.3;

        // Penalize if the next item won't fit in the remaining space
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 3. Efficiency normalization: favor bins that align with the global mean residual
    // This helps keep bins balanced in terms of remaining capacity
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 4. Critical threshold: If this is the only bin that fits the item, 
    // significantly lower its score to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Progression damping: As the stream nears the end, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A new bin (bin_residual == bin_capacity) should be penalized heavily unless all fits are poor.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
