        // and how much space is wasted elsewhere.
        score = 150.0 + (open_bins_count as f64 * 2.5) + (mean_residual * 0.5);

        // If we have many fitting options, opening a new bin is very bad.
        if fitting_bins_count > 0 {
            score += 200.0 * (fitting_bins_count as f64);
        }
