        }

        // Lookahead heuristic: If the next item can fit in the post_residual, reward this placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }

        // Favor bins that are already "tight" to preserve larger empty bins for larger items.
        // We weigh the current bin's residual against the global mean.
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Dynamic horizon adjustment: As we reach the end of the stream, 
    // prioritize closing existing bins over opening new ones.
    if progress > 0.95 && is_new_bin {
        score += 500.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to accommodate future items.
    // If post_residual is < 10, it is often unusable. 
    // We scale this penalty by the inverse of the remaining stream.
    if post_residual > 0 && post_residual < 10 {
