    if bin_residual == bin_capacity {
        score += 40.0 * progress;
        // Also penalize if there are other bins that could have taken this item.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Balance the usage of open bins: penalize bins that deviate from the current mean residual.
    // This promotes uniform distribution of space across open bins.
    let residual_deviation = (post_res - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
