    // If bin_residual == bin_capacity (New Bin Case)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the item is large
        // and we want to preserve smaller gaps in existing bins.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (progress * 20.0); 

        // If we have few open bins, opening a new one is expensive.
        if open_bins_count < 3 {
            score += 100.0;
        }
    } else {
        // 5. Fragmentation Avoidance:
        // If the post_residual is in the "dead zone" (e.g., 1-9), it's likely unusable.
        // Penalize creating small gaps unless it's a very good fit.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 6. Distribution Balancing:
        // If this bin's residual is significantly lower than the mean, it's a "tight" bin.
        // We want to keep packing into tight bins to keep others empty.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 7. Last Chance Logic:
    // If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
