    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If next_item_size fits in the current post_residual, reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / 100.0);
    }

    // Dynamic threshold: As the stream progresses, increase pressure to pack tighter
    // by penalizing the opening of new bins (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // The cost of opening a new bin increases as we approach the end of the stream
        // to prevent fragmentation early on.
        score += 30.0 + (40.0 * progress.powi(2));
    }

    // Interaction with global state: 
    // If we have many open bins, penalize keeping a bin with a very small residual 
    // if it doesn't fit the next item, encouraging consolidation.
    if open_bins_count > 5 {
        score += (mean_residual - post) * 0.5;
    }

    // Favor bins that have a residual closest to the average to keep bin fullness uniform
    score += (post - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (1-9)
    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins where post_residual
    // is closest to the next_item_size or a multiple of it, reducing wasted space.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.4;

        // Penalize if the current placement prevents the next item from fitting
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 3. New Bin Thresholding: If we are forced to open a new bin, verify if the current 
    // bin residual is "too good" to waste.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is high enough that we don't 
        // desperately need to pack into tight spaces.
        score += mean_residual * 0.5;
        if fitting_bins_count > 0 {
            score += 40.0; // Strong penalty for opening new bins if fit exists
        }
    }

    // 4. Global Density Pressure: As the stream progresses, prioritize closing bins
    // to keep open_bins_count low, favoring placements that leave post_residual near 0.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 2.0;

    // 5. Harmonic Slotting: Penalize residuals that create "dead zones" (e.g., 20-30 range)
    // which are often inefficient for items distributed in the 10-80 range.
    if post_residual >= 20 && post_residual <= 30 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

