    }

    // 2. Open bins pressure: If many bins are open, we want to consolidate. 
    // We penalize opening a new bin (bin_residual == bin_capacity) if fitting_bins_count > 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
