        score += residual_diff * 0.2;
    }

    // Criticality check: If this is the only bin that can fit the item, 
    // heavily prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Final normalization: prevent negative scores from dominating the "new bin" decision
    // while keeping the relative order of existing bins intact.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
