        let completion_ratio = step_index as f64 / total_items as f64;
        let openness_penalty = (open_bins_count as f64 * 5.0) - (mean_residual * 0.5);
        score = 45.0 + openness_penalty + (completion_ratio * 10.0);
    } else {
