    // or if the current item is very large (e.g., > 70).
    if bin_residual == bin_capacity {
        if item_size < 70 && open_bins_count > 0 {
            score += 120.0; // Strong penalty for opening new bins prematurely
        } else {
            score += 40.0; // Baseline cost for new bin
        }
    }

    // 5. Progression Weighting: As the stream nears the end, prioritize tightly 
    // packing remaining items by reducing the penalty for small residuals.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the minimum likely item (10)
    // are highly undesirable as they cannot accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
