    // Heuristic: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // Lookahead logic: If the next item is large, avoid creating a post_residual
    // that is too small to fit the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
