    // 3. New Bin Penalty: If the bin is new (bin_residual == capacity), 
    // we only open it if the current fit is poor or we are near the end of the stream.
    if bin_residual == bin_capacity {
        score += 35.0; // Base penalty for opening a new bin
        // Reduce penalty if we are desperate (few fitting options) or nearing the end
        if fitting_bins_count == 0 {
