    // Non-linear coupling: penalize creating "dead space" that is too small for future items.
    // If post_residual is small but > 0, it creates fragmentation.
    // We penalize based on the next_item_size to predict if this bin becomes unusable.
    if post_residual > 0 && next_item_size > post_residual {
