            score -= 50.0;
        }
    } else {
        // Favor bins that bring us closer to the mean_residual of the system
        // to keep bin fullness uniform.
        score += (post - mean_residual).abs() * 0.2;
    }

    // Final scaling: favor bins that leave space for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
