    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - post / 10.0);
    }

    // Reward bins that can accommodate the next item (Lookahead).
    // If this bin fits the next item, reduce its score.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: Near the end of the stream, prioritize closing bins
    // by heavily penalizing new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Coupling with mean_residual: If this bin's post_residual is significantly 
    // worse than the average, penalize it to keep open bins balanced.
    if post > mean_residual {
        score += 15.0 * (post - mean_residual) / bin_capacity as f64;
    }

    // If this is the only bin that fits the current item, prioritize it 
    // heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
