    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (near-full bins are good, but tiny remainders are bad)
    // We favor post_residuals that are either 0 or large enough to accommodate the next item.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // 2. Global State: Discourage opening new bins early in the stream
    if is_new_bin {
        score += 15.0 * (1.0 - progress);
        // Penalty if we have open bins that could fit the item
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 3. Lookahead Calibration: If the next item is large, prioritize bins that keep enough space
    if next_item_size > 0 && post_residual < next_item_size && !is_new_bin {
        score += 10.0;
    }

    // 4. Distribution Balancing: Avoid creating bins with residuals significantly lower than the global mean
    if !is_new_bin && (post_residual as f64) < (mean_residual * 0.5) {
        score += 5.0;
    }

    // 5. Hard Constraint: If fitting_bins_count is 1 and this is the only bin that fits, 
    // prioritize this bin to avoid fragmentation, unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle).
    let mut score = post;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a dynamic penalty
    // that decreases as the stream progresses, allowing more bin-opening in late game.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5);
    }

    // Lookahead coupling:
    // If the next item is large, penalize bins that would leave a small "sliver" of space
    // that is too small for the next item but too large to be considered "tight".
    if next_item_size > 0 {
        let sliver_penalty = if post < next_item_size as f64 && post > 0.0 {
            (next_item_size as f64 - post) * 1.5
        } else {
            0.0
        };
        score += sliver_penalty;
    }

    // Mean residual coupling:
    // Penalize bins that deviate significantly from the mean residual of open bins
    // to keep the packing density uniform across all active bins.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.2;

    // Critical constraint:
    // If this is the only bin that can fit the item (fitting_bins_count == 1),
    // heavily reward choosing this bin to prevent unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
