    };

    // Calculate a lookahead pressure: if the next item is large, 
    // we want to preserve larger residuals (smaller post_residual is better for small items, 
    // but larger post_residual is better for large items).
    let lookahead_factor = if next_item_size > 0 {
        let diff = (next_item_size as f64 - post).abs();
        if post < next_item_size as f64 { 50.0 } else { diff * 0.5 }
    } else {
