        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Encourage filling existing bins to keep open_bins_count low
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 4. Distributional awareness: If the post_residual is close to the mean_residual
    // of other bins, it creates a balanced state which is generally stable.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
