    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 7. Last Chance Constraint: If this is the only bin that fits the current item, lower its score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" option heavily early on, but allow it if it's the only way to avoid fragmentation.
    // If bin_residual == bin_capacity, we are evaluating the choice of opening a fresh bin.
    let is_new_bin = bin_residual == bin_capacity;

    // Base heuristic: Best-Fit (minimizing post_residual)
    // We add a non-linear penalty for small post_residuals (fragmentation) that increases as the stream progresses.
    // A small post_residual (e.g., 1-5) is often "dead space" that cannot fit future items.
    let fragmentation_penalty = if post < 10.0 {
        (10.0 - post).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead logic: if we know the next item, penalize bins that cannot fit it
    // if we put the current item in this bin.
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            lookahead_penalty = 20.0 * (1.0 - progress);
        }
    }

    // Weighting the open bin count: avoid creating too many bins if we have space elsewhere.
    let bin_density_bias = (open_bins_count as f64 * 0.5) * (1.0 - progress);

    let mut score = post + fragmentation_penalty + lookahead_penalty + bin_density_bias;

    // Adjust the "New Bin" cost:
    // If we have many fitting bins, opening a new one should be very expensive.
    if is_new_bin {
        // If we are forced to open a new bin (no other fits), this score will be compared to others.
        // We set the baseline cost of a new bin to be high.
        score = 45.0 + (progress * 20.0);

        // If there are other bins that could fit the item, penalize the new bin decision even more.
        if fitting_bins_count > 0 {
            score += 100.0 / (fitting_bins_count as f64 + 1.0);
        }
    }

    score
}

