    // Penalty for opening new bins: if bin_residual == bin_capacity, we are evaluating a new bin.

    let mut score = post;

    // Penalty for creating a "fragment" (very small residual) that is unlikely to fit future items.
    // We favor larger post_residual if it's large enough to fit the average next item.
    let frag_penalty = if post > 0.0 && post < 15.0 {
        20.0 * (1.0 - (post / 15.0))
    } else {
        0.0
    };
    score += frag_penalty;

    // Lookahead coupling: if the next item is large, penalize small residuals in the current bin.
    if next_item_size > 0 {
        let next_size = next_item_size as f64;
        if post < next_size {
            score += (next_size - post) * 0.5;
        }
    }

    // Dynamic thresholding based on stream progress.
    // As we near the end of the stream, prioritize aggressive bin packing (lower residual).
    // If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already, or if we are early in the stream.
        // We penalize the new bin creation more as the stream progresses.
        let new_bin_penalty = 15.0 + (progress * 25.0) + (open_bins_count as f64 * 0.5);
        score += new_bin_penalty;
    } else {
        // If it fits in an existing bin, we slightly favor bins that are already "half-full" 
        // to keep the number of open bins low.
        score -= (bin_capacity as f64 - residual) * 0.1;
    }

    // Influence of fitting_bins_count: If this is the only bin that fits, we MUST take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #811: Harmonic Residual Optimization
    // Targets the minimization of "dead zones" (residuals < 10) while favoring 
    // packing configurations that accommodate the lookahead item.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but unusable (1-9)
    // as they likely become permanent waste.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // significantly prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
