    // 3. Density Balancing: If we are late in the stream, favor utilizing 
    // existing open bins over opening new ones to minimize total bin count.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (20.0 * (1.0 - progress)) + (mean_residual * 0.5);
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, 
    // reward it to prevent premature new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Modulo Alignment: Prefer configurations that leave larger chunks 
    // divisible by common item sizes (e.g., 20, 25, 50).
    let alignment = (post_residual % 20) as f64;
    score += alignment * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
