    // Residuals between 1 and 9 are often impossible to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Best-Fit logic: Prefer bins that leave smaller residuals
    // (Already partially handled by post_residual, but we refine it)
    score += (post_residual as f64) * 0.1;

    // 3. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
