    }

    // 4. Global state: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. New bin handling:
    // If bin_residual == bin_capacity, this is a request to open a new bin.
    // We only open a new bin if we have no good choices (fitting_bins_count is low)
    // or if the current open bins are very crowded (low mean_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Forced to open
        } else {
            // Heavily penalize opening a new bin if other bins can fit the item
            score += 100.0 + (mean_residual * 2.0);
        }
    } else {
        // Encourage using existing bins that have a residual close to the mean_residual
        // to keep bin utilization balanced.
        let diff = (bin_residual as f64 - mean_residual).abs();
        score -= diff * 0.05;
    }

    // 6. Final constraint: Avoid leaving tiny, unusable spaces if possible
    if post_residual == 0 {
        score -= 20.0; // Perfect fit is highly desirable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
