        score = 65.0 + (mean_residual * 0.5);

        // If we are late in the stream, be more aggressive with opening new bins 
        // to avoid stranding items.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 15.0;
    }

    // 4. Fitting Density: 
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Harmonic Class Logic: 
    // Reward bins whose residual aligns with common item size fractions (e.g., 1/2, 1/3 of capacity)
    let harmonic_alignment = (post_residual % 25) as f64;
    score += harmonic_alignment * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
