    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    // Dynamic scaling based on stream progression: late in the stream, 
    // be more aggressive about filling gaps (minimize post-residual strictly).
    score * (1.0 + (0.5 * progress))
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
