    }

    // 6. Progression Bias: As the stream progresses, favor tighter packing to close bins out.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 7. Mean Residual Alignment: Penalize bins that deviate significantly from the mean residual.
    // This keeps the remaining space across bins uniform, increasing the probability that 
    // future items will fit into one of the existing bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

