    };

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next_item, we penalize the current choice.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Progress coupling: As the stream nears the end, become more aggressive at filling bins
    // to avoid leaving too many bins partially full.
    let exhaustion_bonus = (1.0 - progress) * post * 0.5;

    // Favor bins that have a residual close to the current mean_residual to keep bin states uniform,
    // which statistically improves future packing flexibility.
    let uniformity_penalty = (post - mean_residual).abs() * 0.2;

    // Decision logic for New Bin vs Existing:
    // If fitting_bins_count is 1, we are at a "critical" point. Opening a new bin is expensive.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
