    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: higher if there are many already-open bins
        // or if the current item is small enough to likely fit elsewhere later.
        score += 45.0 + (open_bins_count as f64 * 2.5) + (progress * 10.0);
    } else {
        // Reward tight fits (Best Fit principle)
        score += post_residual as f64 * 0.5;

        // Lookahead penalty/reward:
        // If the next item is large and won't fit in the current post_residual, 
        // we penalize this bin to save it for a potentially better match.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 15.0 * (1.0 - progress);
            } else {
                // If the next item *does* fit, we slightly reward this placement
                // to encourage keeping bins "usable" for upcoming items.
                score -= 5.0;
            }
        }

        // Global state heuristic:
        // If the current bin's residual is significantly lower than the mean residual,
        // it's a "tight" bin. Encourage using it to clear it out.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }

        // Urgency: If this is the only bin that can fit the item, prioritize it highly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill later)
    // We penalize post_residuals between 1 and 9 exponentially.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 2.0;
    }

    // Dynamic Lookahead Adaptation: 
    // If we have a next item, we want to favor bins that can accommodate it.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            // Reward bins that have high potential to fit the next item
            score -= (next_item_size as f64 * 0.8);
        }
    }

    // Stream progression logic:
    // As the stream progresses, we become more conservative about opening new bins.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the progress is early.
        // Penalty for opening a new bin increases as we approach the end of the stream.
        score += (open_bins_count as f64 * 5.0) + (progress * 50.0);
    } else {
        // If it's an existing bin, favor those that bring the mean_residual closer to 0
        // to maximize bin utilization.
        score += (post - mean_residual).abs() * 0.5;
    }

    // Criticality check: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot fit common small items (e.g., < 20).
    // If post_residual is in the range [1, 19], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 + (20.0 - post_residual as f64) * 2.5;
    }

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next item.
            score -= 30.0;
        } else {
            // Penalize bins that block the next item from fitting.
            score += 15.0;
        }
    }

    // Harmonic class logic: favor filling bins to high density (close to 0 residual).
    // We heavily penalize opening new bins unless the current best fit is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // High threshold to open a new bin if an existing one works.
            score += 85.0;
        } else {
            // Forced to open a new bin.
            score = 0.0;
        }
    }

    // Adjust score based on mean_residual to prevent fragmentation.
    // If this bin is already "emptier" than the average, we prefer filling it.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Progression scaling: as we approach the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-20 range)
    // Residuals between 1 and 9 are extremely toxic for future packing
    if post_residual > 0 && post_residual < 10 {
        score += 80.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary
    // If it's a new bin, penalize based on current resource utilization
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the fit quality elsewhere is poor
        score += 25.0 + (open_bins_count as f64 * 2.0);
    } else {
        // For existing bins, reward bins that align with the mean to keep residuals uniform
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.5;

        // If this is the last chance to fit in an existing bin, prioritize it strongly
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 4. Progression scaling: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals too small for common items, but too large to be efficient)
    // We penalize post_residual heavily if it's small but not zero (fragmentation)
    if post_residual > 0 && post_residual < 15 {
        score += 45.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into the remaining space, reward this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward bins that have just enough space to hold the next item comfortably
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Penalize if the next item cannot fit in this bin anymore
            score += 25.0;
        }
    }

    // 3. Pressure management: If we are running out of items, be more aggressive about closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 4. Fitting constraints: If this is the last chance for the current item, prioritize it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Mean residual balancing: Prefer bins that stay close to the global mean residual
    // This prevents creating many bins with very different fill levels
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 6. New bin bias: Apply a baseline cost to opening a new bin
    // If bin_residual == bin_capacity, this is a new bin candidate
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

