    // Residuals < 10 are highly undesirable as most items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead logic: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global state awareness: If we are late in the stream, be more conservative
    // about opening new bins. If current bin is empty (new bin candidate), penalize it 
    // unless all other bins are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 20.0);
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item, 
    // heavily reward choosing it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Balance the load: If this bin's residual is significantly lower than the 
    // mean residual of other bins, prefer filling it to keep other bins open for 
    // larger items (Best-Fit principle).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
