}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post-residuals to keep bins tight.
    // 2. Harmonic Class Penalty: If post_residual is small but not zero, it often creates
    //    'dead space' that cannot fit typical items (10-80). We penalize values < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, 
    //    prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Strategic New Bin Avoidance: If this is the only bin that fits the current item,
    //    heavily prioritize it to avoid creating a new bin (which costs capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global Density Balancing: If we have many open bins, penalize opening new ones 
    //    (where bin_residual == bin_capacity) to force consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // Add a progress-based dampener: early in the stream, be more conservative with new bins.
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    // 6. Mean Residual Alignment: Penalize bins that deviate significantly from the mean 
    //    to maintain a uniform distribution of fill levels across active bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
