pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a significant penalty to keep the number of bins low.
    // We calibrate this based on the current progression to allow more bins early if needed.
    if bin_residual == bin_capacity {
        score += 25.0 + (50.0 * (step_index as f64 / total_items as f64));
    } else {
        // 2. Best-Fit Decreasing logic: Favor bins that leave the smallest residual.
        // This is already partially captured by returning post_residual, but we refine it.

        // 3. Lookahead Logic: If the next item fits perfectly into this post_residual,
        // reward this bin heavily to create a "perfect pair".
        if next_item_size > 0 && next_item_size <= post_residual {
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (50.0 - fit_diff * 0.5);
        }

        // 4. Dead-space avoidance: Penalize residuals that are too small to fit any expected item ( < 10)
        // but large enough to be wasteful.
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }

        // 5. Global state balancing: If many bins are open, penalize creating more,
        // but if this bin is the last one that can fit the item, favor using it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // 6. Mean alignment: Penalize bins that drift significantly away from the mean residual
        // to keep the bin distribution uniform.
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We favor placements that minimize post_residual (Best Fit), but penalize 
    // fragmenting space that could accommodate the next_item_size.

    let mut score = post_residual as f64;

    // Penalty for creating "dead space": if the post_residual is too small to fit 
    // any likely item (e.g., < 10), it's often better to have used a different bin.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Global state awareness: if we are near the end of the stream, prioritize 
    // packing tightly over keeping bins open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Discourage opening new bins unless necessary.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean residual is already quite low,
        // or if we have no other choice.
        score += 40.0 - (mean_residual * 0.5);
    }

    // If this is the last fitting bin available, reduce penalty to prevent 
    // premature new bin creation if the fit is decent.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded (dead space)
    // We prioritize keeping the post_residual either as close to 0 as possible (Perfect Fit)
    // or large enough to accommodate the next item (Lookahead optimization).
    let mut score = post * post;

    // Favor bins that fit the next item (Lookahead heuristic)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64).powi(2) * 1.5;
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower mean_residual)
    // to keep the packing density high.
    score += (mean_residual - post) * progress * 10.0;

    // Penalty for opening a new bin:
    // If this is an empty bin (bin_residual == bin_capacity), apply a heavy cost 
    // unless the current open bins are all very poorly suited for the current item.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * (1.0 + progress) * 2.0;
        // Reduce penalty if no other bins can fit the item
        if fitting_bins_count == 0 {
            score -= (bin_capacity as f64) * 1.5;
        }
    }

    // Reward bins that have high utilization after placement (smaller post_residual)
    // attenuated by a non-linear factor of the current open bin count.
    score += (open_bins_count as f64).sqrt() * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
