    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small to fit next_item_size, we penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
