        } else {
            // Reward bins that leave exactly enough room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 4. Harmonic thresholding:
    // If bin_residual == bin_capacity, we are considering opening a new bin.
    // Only open a new bin if the current mean_residual is very high (meaning current bins are mostly empty)
    // or if the item is large (e.g., > 70) and we want to preserve space in existing bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have plenty of open bins that could fit
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
