        } else {
            // Penalize bins that would force the next item into a new bin unnecessarily.
            score += 20.0;
        }
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the bin_residual == bin_capacity and we have many open bins
    // or if the current best fit is extremely poor (leaving very little space).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Always open the first bin.
        } else {
            // High threshold to open a new bin: penalize new bins unless the mean 
            // residual is already very low, indicating we are running out of space.
            score += 45.0 + (mean_residual * 0.5);
        }
    } else {
        // If this is the last fitting bin, prioritize it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Progress-based adjustment: near the end of the stream, be more aggressive
    // about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
