    // Lookahead logic: If a next item exists, penalize bins that cannot fit it after this placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Pressure to consolidate: If we have many open bins, penalize opening a new one or using a "loose" bin.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have very few open bins, or if all existing bins are a bad fit.
        score += (open_bins_count as f64) * 15.0;
        if fitting_bins_count > 0 {
            score += 40.0; // Strong penalty against opening a new bin if an existing one works.
        }
    } else {
        // For existing bins, favor those that bring the bin closer to the mean_residual (load balancing).
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // Progression scaling: As the stream nears the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
