            score = 80.0 + (mean_residual * 0.5);
        }
    } else {
        // If this bin is the last chance for this item (fitting_bins_count == 1),
        // prioritize it significantly to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin early in the stream, but allow it if it's the only option.
    // The core objective is to minimize post_residual (Best Fit).
    // We apply a non-linear penalty to post_residual based on the current bin density.
    // A higher post_residual is usually bad, but we modulate this by how many bins are available.

    let mut score = post * (1.0 + (mean_residual / bin_capacity as f64));

    // Lookahead logic: if the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty that decays 
    // as the stream progresses (as it becomes harder to find perfect fits).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high, but decreases as we reach the end of the stream
        // to ensure we don't leave too much empty space at the very end.
        score += (bin_capacity as f64) * (1.5 - progress);
    }

    // If this bin is the only one that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalty for creating "fragmented" space: if the post_residual is small but not zero,
    // it's often worse than a slightly larger residual that might fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones" (residuals that are too small to fit common items)
    // We heavily penalize small residuals that are strictly less than the minimum likely item (10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, avoid bins that leave a small post_residual
    // that won't be useful for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that leave space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Harmonic/Modulo bias: Prefer residuals that are multiples of 20 (factors of 100)
    // to keep the bin state "clean" for future packing.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Strategy for opening new bins:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the current
    // fits are truly suboptimal (high penalty).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (to avoid fragmentation)
        // or if all current bins lead to high penalty residuals.
        score += (open_bins_count as f64 * 2.5);
    } else {
        // Prefer bins that are already "half-full" to maintain packing density
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 15.0;
    }

    // Progression scaling: As we approach the end of the stream, prioritize closing bins
    // by rewarding placements that result in very small residuals.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 5 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize "dead space" (gaps < 10)
    // that cannot fit subsequent items, while managing the count of open bins.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (residual < 10) that is likely unusable.
    // We increase score (penalize) if the remaining space is small but > 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Lookahead logic: if next_item_size exists and doesn't fit in the new post_residual,
    // we penalize this placement to keep the bin flexible for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Encourage filling bins that are already closer to the mean_residual to keep
    // bin utilization uniform, reducing the number of "sparse" open bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // Scale penalty by open_bins_count to discourage opening new bins (or keeping too many open)
    // as the stream progresses.
    let progression = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progression * 2.0);

    // If this is a new bin (bin_residual == bin_capacity), make it a "last resort"
    // by adding a baseline cost based on the number of already open bins.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // If this is the only bin that fits the item, prioritize it heavily by reducing the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals smaller than the smallest likely items, 10).
    // If post_residual is in (0, 10), it's a high-risk space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Aggressive 2-step lookahead: 
    // Reward bins where the post_residual can perfectly or nearly accommodate the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff == 0 {
            score -= 40.0; // Perfect fit reward
        } else if diff < 10 {
            score -= 20.0; // Near fit reward
        }
    }

    // 3. Pressure to consolidate:
    // If we have many open bins, penalize opening a new one or using a bin that deviates 
    // significantly from the mean residual of the current set.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have fitting candidates.
        score += 60.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that bring the current residual closer to the global mean.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Scarcity handling:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression scaling:
    // As the stream nears the end, be more conservative with space utilization.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely.
    if is_new_bin {
        score += 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Lookahead: If the next item fits into the current post_residual, 
        // we reward this bin heavily to preserve packing density.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // Avoid "dead zones": If post_residual is too small to fit any likely item 
        // (assume < 10 is risky), we penalize it.
        if post_residual < 10 {
            score += 12.0;
        }

        // Global state balancing: If we have many open bins, penalize taking up 
        // space in a bin that is already quite full to encourage consolidation.
        if open_bins_count > 5 && post_residual < 20 {
            score += 5.0;
        }

        // Encourage filling bins that are already closer to the mean_residual
        // to keep the bin distribution uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) with a base cost that scales with progress.
    // As the stream nears completion, we become more conservative about opening new bins.
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new * (100.0 * (1.0 + progress));

    // Best-Fit Decreasing logic: favor small post_residual (tight packing).
    // Add a non-linear penalty for "dead space" (post_residual).
    // We square the post_residual to heavily penalize large gaps.
    let fit_score = (post * post) / 10.0;

    // Lookahead logic: if next_item_size is large, avoid leaving a residual that is too small for it.
    // If post_residual is positive but smaller than next_item_size, we create a "wasted" slot.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Interaction term: favor bins that are already "fuller" (lower mean_residual) to maintain
    // a compact frontier.
    let compactness_bonus = (mean_residual - post) * (1.0 - progress);

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new one.
    let desperation_bonus = if fitting_bins_count == 1 && is_new == 0.0 { -50.0 } else { 0.0 };

    new_bin_penalty + fit_score + lookahead_penalty + compactness_bonus + desperation_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": residuals smaller than the smallest likely item (e.g., < 10)
    // unless it results in a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Harmonic balance: Favor bins that maintain a residual close to the global mean
    // to keep the packing density uniform across all active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 4. New bin thresholding: Increase the cost of opening a new bin (where bin_residual == bin_capacity)
    // based on how many bins are already open and the progress of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Penalize opening new bins more as the stream progresses to consolidate packing.
        score += 20.0 + (progress * 30.0) + (open_bins_count as f64 * 2.0);
    }

    // 5. Last chance mitigation: If this is the only bin that fits the item, 
    // reduce its score to ensure we don't prematurely open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. Modulo-based "Tight Fit" reward: Encourage bins that approach 
    // capacity thresholds (e.g., leaving a remainder that is a multiple of 10).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" gaps (dead space < 10)
    // If post_residual is between 1 and 9, it is extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If next_item can fit in post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Global pressure: Penalize opening too many bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // 4. If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless fitting_bins_count is 0 (forced move).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if an existing one can take it
            score += 60.0;
        } else {
            // Neutralize penalty if no other choice
            score -= 20.0;
        }
    }

    // 5. Prefer bins where the post_residual is closer to the mean_residual of other bins
    // to keep bin utilization profiles uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating a new bin unless absolutely necessary or highly efficient
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
