    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Balancing: Align with the mean_residual to keep bin usage uniform
    // If this bin is significantly emptier than others, prioritize filling it
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // 5. Progression scaling: Be more aggressive about packing as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

