}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" (wasteful residual)
    // We penalize high post_residual values, but scale by the number of currently open bins
    // to encourage consolidation in later stages of the stream.
    score += (post_residual as f64).powf(1.5) * (1.0 + open_bins_count as f64 * 0.05);

    // Lookahead logic: If the next item fits into the current bin's post_residual,
    // we heavily favor this bin (Best-Fit-Decreasing style logic).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // New Bin Logic: If this is a new bin candidate, only pick it if the
