    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score += 45.0;
        // If we have many bins that can fit the item, opening a new one is inefficient.
        score += (fitting_bins_count as f64) * 30.0;
        // As we approach the end of the stream, opening new bins becomes increasingly expensive.
        score += progress * 50.0;
    } else {
        // If it's an existing bin, reward filling it up to avoid fragmentation.
        // If post_residual is small, it's a "tight fit" (Best Fit).
        score -= (bin_capacity - post_residual) as f64 * 0.8;
    }

    // Global state adjustment: If the mean residual of existing bins is already high,
