    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when many are already open,
    // but reward using existing bins to keep the open_bins_count low.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin.
        score += (open_bins_count as f64) * 5.0;

        // If we have many fitting bins, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 100.0 * (fitting_bins_count as f64);
