pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of "orphaned" space (small gaps that are hard to fill later)
    // We penalize post_residual exponentially as it approaches zero, unless it is exactly zero.
    let gap_penalty = if post == 0.0 { 0.0 } else { 1.0 / (post + 0.1).sqrt() };

    // Leverage lookahead: if the next item fits into the current post_residual, 
    // prioritize this bin heavily (negative reward).
    let lookahead_reward = if next_item_size > 0 && (post_residual >= next_item_size) {
        -50.0 * (1.0 - progress)
    } else {
