    };

    // Interaction between fitting_bins_count and open_bins_count:
    // If we have many fitting bins, we want to be more selective (higher score to reject poor fits).
    // If fitting_bins_count is 1, we are desperate; lower the score to accept the fit.
    let desperation_factor = if fitting_bins_count <= 1 { -20.0 } else { (fitting_bins_count as f64).ln() * 5.0 };

    // Polynomial coupling: post_residual modulated by progress.
    // Early in the stream, we prefer tighter fits (lower post). 
    // Late in the stream, we are more tolerant of slack to avoid opening new bins.
    let base_score = post * (1.0 + progress.powi(2));

    // New bin logic:
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    // We only want to open it if the cost of placing in existing bins is high.
    let score = if bin_residual == bin_capacity {
        // High constant to discourage opening new bins unless necessary
        45.0 + (open_bins_count as f64 * 2.0)
    } else {
        base_score + gap_penalty + lookahead_reward + desperation_factor
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
