    }

    // Lookahead logic: if the next item is large, favor bins that leave enough room.
    if next_item_size > 0 {
        let diff = post as i32 - next_item_size as i32;
        if diff < 0 {
            // If this bin cannot fit the next item, penalize it slightly 
            // unless it's a perfect fit (post == 0).
            score += 15.0 * (1.0 - progress);
        } else {
            // If it can fit, reward it based on how tightly it fits.
            score -= 10.0 * (1.0 - (diff as f64 / bin_capacity as f64));
        }
    }

    // Dynamic pressure: as the stream progresses, prioritize closing bins (lower open_bins_count).
    // Penalize opening a new bin (where bin_residual == bin_capacity) increasingly over time.
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
        // Also penalize if we have many bins already open to encourage consolidation.
        score += open_bins_count as f64 * 2.0;
    }

    // Favor bins that are already "half-full" or better to keep the distribution compact.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual.
    // We penalize large post_residuals to keep bins tightly packed.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Awareness:
    // If post_residual is small, it might be unusable for future items. 
    // We heavily penalize "dead space" (e.g., 1-9) unless it perfectly matches the next item.
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 50.0; // Penalize creating a hole that cannot fit the lookahead
        } else {
            score += 25.0; // General penalty for creating small, unusable slivers
        }
    }

    // 3. Lookahead Synergy:
    // If the next item fits perfectly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_delta = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_delta) * 0.5;
    }

    // 4. Global Density Control:
    // If we have many open bins, prioritize filling existing ones to keep open_bins_count low.
    // If bin_residual == bin_capacity, this is a "New Bin" candidate.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist.
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Must open a new bin, neutralize the penalty.
            score = 0.0;
        }
    } else {
        // Reward closing the gap toward the mean residual to maintain uniform bin states.
        score -= (mean_residual - post_residual as f64).abs() * 0.2;
    }

    // 5. Progression Scaling:
    // Toward the end of the stream, be more aggressive with packing (less concern for future variance).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // (10-20 range) but large enough to be wasted.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit in the current post_residual, 
    // prioritize this bin highly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Global Bin Pressure: As the stream progresses, favor packing tighter to 
    // minimize the footprint of open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // 4. New Bin Penalty: If this is a new bin (residual == capacity), apply a 
