    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    }

    // 5. Fitting Context: If this is the only bin capable of holding the item, 
    // reduce the score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate significantly from 
    // the mean residual to encourage uniform bin usage.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
