pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // post_residual represents the space left. We want to minimize this (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only do it if the fit is truly terrible.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // Lookahead logic: If the next item exists, penalize bins that leave just enough space 
    // to miss the next item, or reward bins that create space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin is "perfect" for the lookahead, reward it strongly.
            score -= 25.0;
        } else if post_residual > 0 && post_residual < 10 {
            // This bin creates "dead space" that is likely unusable. Penalize it.
            score += 15.0;
        }
    }

    // Global state adjustment: If we have many open bins, prioritize filling existing ones
    // to increase packing density (Best Fit Decreasing-like behavior).
    if open_bins_count > 0 {
        let density_factor = (mean_residual / bin_capacity as f64) * 10.0;
        score += density_factor;
    }

    // Dynamic horizon: As the stream nears completion, become more aggressive 
    // about fitting into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // Critical constraint: If this is the last chance to fit the item in an existing bin,
    // lower the score to prioritize it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
