    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * post;

    // Favor bins that result in residuals close to the expected future item size (lookahead coupling).
    // If next_item_size is 0, we treat it as a neutral value (e.g., 30).
    let target = if next_item_size > 0 { next_item_size as f64 } else { 30.0 };
    let fit_error = (post - target).abs();
    score += fit_error * (1.0 + progress);

    // If this is the only bin that fits, we are forced to use it.
    // Lower the score to prioritize picking it over a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
