    // Penalty for creating a new bin: non-linear growth based on progress.
    // We want to avoid opening new bins when many open bins are already underutilized.
    if is_new_bin {
        let utilization_penalty = (open_bins_count as f64) * 200.0 * (1.0 - progress);
        score += 2500.0 + utilization_penalty;
    }

    // Penalize fragmented bins: if post_residual is very small but > 0, 
    // it creates "dead space" that is hard to fill.
    if post > 0.0 && post < 10.0 {
        score += 1000.0 * (1.0 - post / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
