    }

    // 4. Global Pressure: As the stream progresses, favor packing tighter to minimize open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly from the mean_residual
    // to keep the packing density uniform across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size fits perfectly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough room for the next item
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize creating "dead zones" too small for the lookahead item
            score += 40.0;
        }
