    // 3. New Bin Penalty: Heavily penalize opening a new bin unless it's necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0; // Forced to open a new bin
        }
    }

    // 4. Mean Residual balancing: Prefer bins that stay close to the current average 
    // to keep space usage uniform across the set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression scaling: As we reach the end of the stream, be more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Small residuals are usually good, but very small residuals (<5) 
    // often create "orphan" space that cannot fit future items.
    if post_residual > 0 && post_residual < 8 {
        score += 15.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // we prioritize this bin heavily to keep space consolidated.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: Penalize opening new bins unless the current best 
    // fits are exceptionally poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low, 
        // suggesting current bins are too fragmented to be useful.
        if mean_residual > 25.0 && open_bins_count > 2 {
            score -= 10.0;
        } else {
            score += 45.0;
        }
    }

    // 4. Scarcity Penalty: If this is the only bin that can fit the item, 
    // we take it, but penalize it slightly if the resulting residual is "awkward".
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Dynamic Horizon: As we reach the end of the stream, prioritize 
    // tighter packing to close bins efficiently.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating a 'bad' residual (small, unusable gaps)
    // We penalize residuals in the range (0, 10) heavily, as they are unlikely to fit future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // Dynamic thresholding based on stream progress:
    // As we approach the end of the stream, we become more conservative about opening new bins.
    // We reward filling existing bins more aggressively when fitting_bins_count is low.
    let scarcity_factor = if fitting_bins_count > 0 {
        1.0 / (fitting_bins_count as f64).powf(0.5)
    } else {
        100.0 // Penalty for opening new bin
    };

    score += scarcity_factor * (1.0 + progress * 2.0);

    // Coupling with mean_residual to maintain balance across bins
    // If this bin's post_residual is significantly better than the current mean, reward it.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.5;
    }

    // Final adjustment: if this is a new bin (bin_residual == bin_capacity),
    // apply a high cost that decays as the stream progresses, but is generally 
    // discouraged compared to fitting into existing bins.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

