            // Heavily penalize opening a new bin if existing bins can take the current item
            score += 150.0;
        } else {
            // Otherwise, it's necessary
            score -= 10.0;
        }
    }

    // 5. Mean residual pressure: If existing bins are already very full, 
    // favor bins that keep the mean_residual balanced to avoid fragmentation.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    // 6. Fill-rate normalization: Encourage filling bins that are already partially occupied
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is too small to fit the smallest possible 
    // future items (typically 10-20), it is "wasted" space. Penalize post_residuals < 20.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 5.0;
    }

    // 2. Open bins pressure: If we have many open bins, penalize opening a new one 
    // significantly. If fitting_bins_count is 0, we are forced to open a new one.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If we are forced to open a new bin, reduce the penalty relative to poor fits
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
