    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Tight fit reward: Prefer bins that are nearly full after placement (Best Fit strategy).
    // This is inverse to the post_residual, so lower values are better.
    score += (post_residual as f64) * 0.2;

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the 
    // average residual of other open bins to maintain uniform bin usage.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // If the bin is brand new (residual == capacity), we penalize it based on how many
    // existing bins could have fit the item. We only want to open a new bin if the
    // existing options are "too tight" or inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if a slot exists
            return 500.0 + (fitting_bins_count as f64 * 50.0);
        }
        return 200.0;
    }

    let mut score = post_residual as f64;

    // HEURISTIC: Best-Fit Decreasing logic (minimizing post_residual)
    // We adjust the score based on the lookahead next_item_size.
    if next_item_size > 0 {
        // If the post_residual is nearly perfect for the NEXT item, reward this placement
        // heavily. This creates a "perfect pair" effect.
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // If the post_residual is too small to fit the next item, penalize it slightly 
        // to encourage keeping larger gaps for the lookahead item.
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // HEURISTIC: Global density control.
    // If we have many open bins, we want to prioritize filling bins that are 
    // further below the mean_residual to consolidate space.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // HEURISTIC: Last-chance avoidance.
    // If this is the only bin that can fit the current item, prioritize it.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // HEURISTIC: Progression weighting.
    // As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize the post-residual (Best Fit) but penalize fragmentation 
    // based on lookahead (next_item_size) and current bin density.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" (wastage)
    // If we open a new bin, bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to, or if the current bins are very full
        // We add a high base cost to opening a new bin to discourage it
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // We are placing in an existing bin.
        // Reward placements that leave a residual capable of fitting the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Strong reward for "Perfect Pair" potential
            } else if post_residual < 10 {
                // Penalize "slivers" of space that are too small for any likely item
                score += 20.0;
            }
        }
    }

    // Heuristic: As we near the end of the stream, prioritize filling existing bins
    // regardless of residual size to minimize the total count.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // Penalize if this is the ONLY bin that can fit the item
    // (Force consolidation if it's the last chance)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Dynamic pressure: If open_bins_count is high, prioritize tighter packing
    score += (open_bins_count as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residual (Best-Fit principle)
    let mut score = post_res;

    // Penalty for creating "slivers": values < 10 are often unusable for future items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, we penalize the current choice.
    if next_item_size > 0 {
        let diff = next_item_size as f64 - post_res;
        if diff > 0.0 {
