    // Dynamic density management:
    // As the stream progresses, we become more aggressive about filling bins (lowering score)
    // to avoid leaving too many bins partially full near the end.
    let density_factor = (mean_residual / bin_capacity as f64) * 20.0;
    score += (1.0 - progress) * density_factor;

    // Favor using existing bins over opening new ones, but scale by fitting_bins_count.
    // If fitting_bins_count is 0, this is the "New Bin" call.
    if fitting_bins_count == 0 {
        // Penalty for opening a new bin: higher at the start, lower at the end.
        score += 40.0 + (progress * 20.0);
    } else {
        // If this is the only bin that fits the current item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Penalize fragmentation: higher open_bins_count means we should be more selective.
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
