            // Penalize placing an item if it forces the next item into a new bin
            score += 5.0;
        }
    }

    // 4. Thresholding based on bin state
    // If this is the only bin that fits the current item, prioritize it to avoid new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. New bin management
    // If bin_residual == bin_capacity (New Bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the open bins are already very full (high mean_residual penalty)
        // or if we are at the very beginning.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0; // Discourage opening new bins if existing ones have space
        } else {
            score += 30.0; // Base cost to open a new bin
        }
    }

    // 6. Progress-based scaling (late-stage packing)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Near the end of the stream, prioritize tightest fits to minimize remaining bins
        score += (post_residual as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

