    let mut score = post_residual as f64;

    // Penalty for creating "slivers": space too small for any likely future item (10).
    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
