        let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= utilization * 10.0;
    }

    // Adjust for scarcity: if only one bin can fit the item, 
    // it's usually better to use it than to open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
