    // 4. New bin penalty/logic: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the current fit is truly terrible (high score).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;

        // If there are other bins that could fit this, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 5. Reward bins that are "tighter" relative to the mean residual of current bins.
    // This encourages leveling out bin usage.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but heavily penalize opening new bins unless necessary,
    // and reward placements that create space for the next_item_size.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin:
    // If we have other bins that can fit the item, opening a new one is costly.
    if is_new_bin {
