        }
    }

    // 2. Lookahead matching:
    // If the post_residual is close to the next_item_size, prioritize this bin.
    // We want the post_residual to be >= next_item_size if possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit scenario: reward bins that leave exactly enough room for the next item
            let waste = (post_residual - next_item_size) as f64;
            score += waste * 0.5;
        } else {
            // Cannot fit next item: penalize proportionally to how much space is wasted
            score += 20.0 + (next_item_size - post_residual) as f64;
        }
    }

    // 3. Global efficiency balancing:
    // Favor bins that align with the current mean_residual to keep bin states uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Progression scaling:
    // As we approach the end of the stream, prioritize tight packing (Best-Fit behavior).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the "leftover" space. We want to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

