        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // 2. Harmonic Lookahead: If next_item_size is large, prioritize larger residuals
    // If next_item_size > post_residual, this bin is "blocked" for the next item.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 25.0; // Penalty for blocking the next item
        } else {
            score -= 15.0; // Reward for enabling the next item
        }
    }

    // 3. Pressure management: If we are running out of bins or space, prefer tighter packing
    let progress = step_index as f64 / total_items as f64;
    if fitting_bins_count == 1 {
        // Last chance to fit in an existing bin, reduce penalty for poor fits
        score -= 10.0;
    }

    // 4. Harmonic balance: Favor bins that stay near the global mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only open a new bin if the score is significantly lower than existing fits.
    if bin_residual == bin_capacity {
        // Increase cost of new bin as we progress through the stream to encourage consolidation
        score = 35.0 + (progress * 20.0);
    }

    score
