        let urgency = progress * 20.0;
        score += 25.0 + fragmentation_penalty - urgency;
    } else {
        // 4. Fitting Bin Scarcity:
        // If this is the only bin that can fit the current item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Residual Balancing:
        // Penalize bins that leave very small, unusable gaps (e.g., < 10, since min size is 10).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }
    }

    // 6. Global efficiency: Favor keeping the number of open bins low.
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement.
    // Lower residual is generally better (Best Fit).
    let mut score = post;

    // Penalty for leaving a bin with a "dead zone" (1-9 space) which is impossible to fill.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Dynamic Lookahead coupling:
    // If next_item_size is large, penalize small post_residuals that would block the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.5;
        }
    }

    // Progression coupling:
    // As the stream approaches the end, prioritize closing bins (lower open_bins_count)
    // rather than keeping many bins partially full.
    score += (open_bins_count as f64) * progress * 10.0;

    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it.
    // We only open a new bin if the current fit is extremely poor or we are near the end.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin.
        score += 45.0;
        // As the stream progresses, the cost of opening a new bin decreases relative 
        // to the efficiency of the remaining packing.
        score -= progress * 20.0;
    } else {
        // If it's an existing bin, reward bins that are closer to the global mean_residual.
        // This encourages "leveling" the bins to avoid outliers.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
