    }

    // 4. Harmonic coupling: favoring bins where the post_residual is a multiple of 
    // common item sizes or fractions of the capacity.
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 5. Manage New Bin Thresholds:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only open a new bin if the existing fits are "bad" (e.g., high penalty).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual is already quite low,
            // or if we have many bins open and the current fit is poor.
            score = 25.0 + (open_bins_count as f64 * 0.5);
        }
    }

    // 6. Global density pressure:
    // As the stream progresses, tighten the tolerance for creating new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
