pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As post_res approaches 0, the penalty increases quadratically to avoid "tight" fits that leave unusable space.
    let fragmentation_penalty = if post_res < 15.0 {
        (15.0 - post_res).powi(2) * 2.5
    } else {
        0.0
    };

    // Reward bins that keep the mean residual of the system balanced.
    // If the current bin's post_residual is close to the global mean, it indicates a stable packing.
    let balance_score = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, favor larger post_residuals to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 5.0
    } else {
        0.0
    };

    // Progression weight: As the stream nears the end, become more aggressive about filling bins (Best Fit).
    // Early on, allow more variance (First Fit / Slack).
    let progression_factor = 1.0 + (progress * 2.0);

    // New bin logic:
    // If bin_residual == bin_capacity, this is a new bin candidate. 
    // Penalize opening a new bin heavily unless the current open bins are too full to be useful.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
