            (50.0 + (open_bins_count as f64 * 2.0)) * progression_factor
        }
    } else {
        0.0
    };

    let score = (post_res * 0.1) + fragmentation_penalty + balance_score + lookahead_penalty + new_bin_penalty;

    score
}

