    // We heavily penalize large post_residuals to force tight packing.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: If post_residual is small, it might be unusable for future items.
    // We penalize "dead zones" (e.g., 1-9 remaining space) because they rarely fit items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Awareness: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin utilization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic Scaling: Penalize opening new bins unless the current bins are "crowded".
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (bins are full).
        if mean_residual > 15.0 {
            score += 20.0;
        } else {
            score += 80.0; // High penalty to discourage opening new bins prematurely.
        }
    }

    // 5. Fitting Constraint: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progressive Pressure: As the stream nears completion, become more aggressive 
    // about using existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 100.0);
    }

    score
}

