    // We use a non-linear penalty for "near-empty" space created by the placement.
    // If post_residual is small but > 0, it's often better than larger space 
    // unless the next item is large.
    let mut score = post * 1.5;

    // Favor bins that result in a residual close to the mean residual of other bins,
    // promoting uniformity in bin state.
    score += (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if the next item is large, avoid leaving a small residual 
    // that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 2.0;
