    // Dynamic thresholding: as we progress through the stream, become more aggressive 
    // about filling bins tightly to avoid opening new ones.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // Penalize bins that deviate significantly from the average capacity usage.
    score += (open_bins_count as f64 * 5.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
