    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This creates "bins of opportunity" for future items.
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
        score += harmonic_penalty * 0.2;
    }

    // 3. Lookahead Integration: If the next item fits into the current post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
