    let mut score = post;

    // Penalty for creating a 'dead zone' (residual too small to fit common items)
    // We penalize residuals that are non-zero but smaller than the minimum likely item size
    if post > 0.0 && post < 15.0 {
        score += 25.0 * (1.0 - (post / 15.0));
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - progress);
        } else {
