    // Encourage filling bins earlier in the stream to consolidate packing
    // As progress approaches 1.0, we become more desperate to fit items into existing bins
    let consolidation_pressure = 40.0 * progress;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we progress through the stream
        score += 35.0 + consolidation_pressure;
    } else {
        // Reward for using existing bins, scaled by how well the item fits
        score -= (1.0 - (post / bin_capacity as f64)) * consolidation_pressure;
    }

    // Penalty if this is the last fitting bin available to prevent premature bin opening
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global balance: penalize deviation from the mean residual to keep bins packed evenly
    let residual_diff = (post - mean_residual).abs();
    score += 0.5 * residual_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
