        let gap_after_next = (post_residual - next_item_size) as f64;
        if gap_after_next == 0.0 {
            score -= 40.0;
        } else if gap_after_next < 10.0 {
            score += 20.0; // Avoid creating a new tiny gap for the future
        }
    }

    // 3. Open Bin Pressure: Penalize opening new bins unless necessary.
    // If this is a brand new bin (bin_residual == bin_capacity)...
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if no other bin fits well.
        score += (open_bins_count as f64) * 5.0;
        if fitting_bins_count > 0 {
            score += 30.0; // Discourage opening new bin if existing bins can take the item
        }
    } else {
        // Reward filling existing bins to keep open_bins_count low.
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. Mean Residual Balancing: Prefer bins that are closer to the current average 
    // to keep the bin distribution uniform (Best-Fit archetype).
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize the creation of small, unusable gaps (1..9).
    // Small gaps often result in "dead space" that cannot fit subsequent items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the resulting post_residual,
    // prioritize this bin heavily to clear space for future items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
