            score += 15.0;
        }
    }

    // 3. Density Balancing: Compare post_residual to the mean_residual of open bins.
    // We want to keep residuals somewhat uniform to maintain flexibility.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost based on
    // how many other bins could have accepted the item.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin if we have existing bins that could fit the item.
        score += (fitting_bins_count as f64 * 40.0);

        // As the process nears completion, discourage opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 50.0;
    } else {
