    // too large to fit the next expected item (or average item size), penalize it.
    // We use the mean_residual to gauge the global state of the bins.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 && post_res > 0.0 {
            // Penalize small gaps that cannot fit the immediate next item
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Dynamic threshold: As we progress through the stream, we become more aggressive
    // about opening new bins if the current fit is poor (Best Fit vs First Fit trade-off).
    // If we are at the end of the stream, prioritize tight packing.
    if bin_residual == bin_capacity {
        // This is the cost to open a new bin. 
        // We scale this cost based on how many bins are already open and the progress.
        // Opening a new bin becomes increasingly expensive as we approach the end.
        score = 25.0 + (progress * 50.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Encourage filling bins that are already closer to the mean_residual
        // to keep the distribution of bin usage uniform.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2;

        // If this is the only bin that fits the item, heavily reward it to avoid 
        // unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

