    // 5. Mean residual balancing:
    // Penalize bins that deviate significantly from the mean_residual to keep bins uniform.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Progressive thresholding (as stream nears completion):
    // Near the end, prioritize closing bins (lower residuals are better).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

