    // to minimize the number of open bins.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Global State Balancing: Discourage opening new bins if there are many bins with high residuals.
    // If we are considering a new bin (bin_residual == bin_capacity), penalize it 
    // unless the mean residual is already quite low.
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual > 20.0 {
            score += 15.0;
        }
    }

    // 5. Scarcity Penalty: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Tight Fit Bonus: If the item fills the bin almost perfectly, reward it.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) by squaring, 
    // but modulate this penalty as the stream progresses.
    // Near the end of the stream, prioritize tight packing (Best-Fit).
    let fragmentation_penalty = if post < 10.0 {
        (10.0 - post).powf(2.0) * (2.0 - progress)
    } else {
        0.0
    };

    // Use lookahead to minimize the impact of the next item.
    // If the next item fits into the post_residual, reward it (negative score).
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -(post - next_item_size as f64).powf(1.5)
    } else if next_item_size > 0 {
        // If it doesn't fit, penalize the bin proportionally to the wasted space
        (next_item_size as f64 - post).sqrt() * 5.0
    } else {
        0.0
    };

    // Reward bins that are closer to the global mean to maintain uniformity
    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    // If this is a new bin (residual == capacity), penalize it heavily 
    // unless it is the only option or we are near the end of the stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0
        } else {
            // Gradually reduce the cost of opening new bins as the stream progresses 
            // to avoid extreme fragmentation in the final stages.
            (50.0 / (progress + 0.1))
        }
    } else {
        0.0
    };

    post + fragmentation_penalty + lookahead_bonus + deviation_penalty + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

