    }

    // 2. Harmonic Class Logic: Favor bins that leave remainders matching common future item sizes
    // If the post_residual is a multiple of common item sizes, it's more likely to be filled later
    if next_item_size > 0 {
        let remainder_mod = post_residual % next_item_size;
        score += remainder_mod as f64 * 0.5;
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless the current fit is terrible
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are extremely crowded
        score += 45.0;
        if mean_residual > 20.0 {
            score -= 20.0;
        }
    }

    // 4. Scarcity Constraint: If this is the only bin that fits the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Lookahead integration: If the next item fits perfectly into the post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 25.0;
        } else if gap_after_next < 10 {
            score += 15.0; // Avoid "almost perfect" fits that leave tiny slivers
        }
    }

    // 6. Global Progression: As we approach the end of the stream, prioritize packing tighter
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (bin_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
