    // If few bins are open, be more cautious about creating new ones.
    if is_new_bin {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins can fit the item
            score += 60.0 + (fitting_bins_count as f64 * 15.0);
        }
        // Early in the stream, favor opening new bins slightly less
        score += (1.0 - progress) * 10.0;
    } else {
        // Reward filling bins that are already "below average" in terms of fullness
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        let mean_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        if fullness < mean_fullness {
            score -= 5.0;
        }
    }

    // 5. Dynamic threshold for final items
    // As we approach the end of the stream, prioritize closing bins over opening new ones
    if progress > 0.9 && is_new_bin {
