    // Dynamic pressure: As the stream progresses, favor packing tighter (lower mean_residual)
    // to keep the number of open bins under control.
    score += (mean_residual - post_res) * progress;

    // Reward bins that have high utilization (low post_residual)
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
