    // Interaction term between current residual and mean_residual to balance load.
    let balance_factor = (post - mean_residual).powi(2) * 0.1;

    base_score + fragmentation_penalty + lookahead_penalty + progress_bias + balance_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic penalty: heavily penalize post_residuals that are small but unusable 
    //    for common sizes (e.g., < 10), unless the bin is near full.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
