    // 3. Lookahead optimization: 
    // If we have a next item, penalize bins that cannot fit the next item after this one.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. New bin thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the mean residual is already quite low, 
    // or if the current item is very large and would leave a terrible gap elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Must open
        } else {
            // Heavily penalize opening a new bin if we have fitting options
            score = 150.0;
        }
    }

    // 5. Progression awareness:
    // As we near the end of the stream, prioritize clearing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Harmonic clustering:
    // Penalize bins that deviate significantly from the mean residual to keep bin density uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
