pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize Best-Fit (minimize post_residual).
    // We add a penalty for "fragmentation" (small post_residual that is hard to fill).
    // The penalty is non-linear: very small residuals (1-10) are penalized heavily 
    // unless the stream is nearly finished.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, penalize.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // New bin logic: if bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the existing options are very poor (high mean_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_score = if is_new_bin {
        // Only open a new bin if we have many bins open but they are all poorly utilized.
        if open_bins_count > 0 && mean_residual < 30.0 {
            100.0 + (open_bins_count as f64 * 2.0)
        } else {
            40.0 - (progress * 10.0)
        }
    } else {
        // For existing bins, minimize the residual while avoiding the "dead zone".
        post + fragmentation_penalty + lookahead_penalty
    };

    // Bias against opening new bins early in the stream.
    let score = if is_new_bin {
        new_bin_score
    } else {
        // Bias towards fitting items into bins that are already "half-full"
        let utilization_bias = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        new_bin_score - (utilization_bias * 5.0)
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
