    }

    // 2. Dynamic thresholding for opening new bins
    // As the stream progresses, become more conservative about opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item
            score += 60.0 + (progress * 40.0);
        } else {
            // If no other bin fits, this is a necessary evil, but favor bins that 
            // result in a "cleaner" residual relative to the global mean.
            score -= (mean_residual - post_residual as f64).abs() * 0.1;
        }
    } else {
        // 3. Best-Fit Decreasing logic: reward filling bins tightly
        // Reward bins that have less space than the average, effectively packing them first.
        score += (post_residual as f64 - mean_residual) * 0.5;

        // 4. If this is the last chance for this item (fitting_bins_count == 1), 
        // give it a slight priority boost to avoid opening a new bin later.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Global pressure: if we have too many open bins, penalize non-tight fits
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" option: If bin_residual == bin_capacity, 
    // it represents an empty bin. We only choose this if the fitting bins 
    // result in extremely poor post_residuals (fragmentation).
    let is_new_bin = bin_residual == bin_capacity;

    // Calculate a base score based on the remaining space (Best Fit principle).
    // We want to minimize post_residual (the space left over).
    let mut score = post * post; 

    // Non-linear coupling: As the stream progresses, become more conservative 
    // about opening new bins. 
    if is_new_bin {
        // The cost of a new bin is the capacity minus the potential to fit the next item.
        // We modulate this by progress to discourage new bins late in the stream.
        score = (bin_capacity as f64 * 0.75) + (progress * 100.0);

        // If the next item fits into this new bin, reduce the penalty.
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= (bin_capacity - item_size - next_item_size) as f64 * 0.5;
        }
    } else {
        // For existing bins, incorporate the proximity to the mean residual.
        // This encourages "leveling" the bins (keeping them similarly full).
        let imbalance = (post - mean_residual).abs();
        score += imbalance * 1.5;

        // Penalize bins that would leave a very small, unusable gap (e.g., < 10).
        if post > 0.0 && post < 10.0 {
            score += (10.0 - post) * 10.0;
        }

        // Lookahead bonus: if this bin fits the next item, lower the score.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.8;
        }
    }

    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic penalty for small residuals that can't fit likely future items
    // If post_residual is small but > 0, it often creates "dead space" that cannot fit 
    // common item sizes (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead synergy: if the next item fits perfectly into the post_residual, 
    // prioritize this bin highly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly 0 space or space for small items
        score -= (100.0 - diff) * 0.5;
    }

    // 4. Thresholding: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0;
        } else {
            score -= 50.0; // Forced to open new bin
        }
    }

    // 5. Harmonic balancing: Penalize bins that deviate significantly from the mean residual
    // to keep bin utilization uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Progressive tightening: As we approach the end of the stream, prioritize 
    // filling bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is highly likely to be wasted.
    // We penalize this heavily to force the algorithm to seek "cleaner" fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Open Bin Pressure: Penalize opening new bins when existing ones are available.
    // We increase the score of a "new bin" (bin_residual == bin_capacity) based on how many bins are already open.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64) * 2.5;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, 
    // significantly reward this placement (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Tightness Bias: Prefer bins that result in a very tight fit (post_residual == 0).
    if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Mean residual equilibrium: Penalize bins that deviate significantly from the 
    // current mean residual to keep bin capacities balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Last-chance logic: If this is the only bin that fits, heavily discount the score
    // to prevent unnecessary bin creation, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely.
    if bin_residual == bin_capacity {
        score += 50.0; 
        if open_bins_count > 0 {
            score += 25.0 * (open_bins_count as f64).sqrt();
        }
    }

    // 2. Lookahead matching: reward bins where the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for "perfect" or "near-perfect" future fit.
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (20.0 - fit_diff).max(0.0);
        } else {
            // Penalize creating a bin that cannot fit the next item if we are running out of space.
            score += 5.0;
        }
    }

    // 3. Balance towards the mean residual to keep bin levels uniform (prevent "jagged" bin distribution).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 4. Criticality: If this is the only bin that fits, prioritize it heavily (avoid new bin creation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression scaling: Be more conservative with new bin creation as the stream nears the end.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating small "dead zones" (unusable fragments)
    // Residuals between 1 and 9 are highly inefficient for the given item range (10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if we know the next item, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward bins that maintain capacity for the next item
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Global state optimization: balance the load
    // Encourage using bins that are closer to the mean residual to keep them packed uniformly
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decays as the stream progresses, but is generally discouraged 
    // unless the fit in existing bins is extremely poor (high post_residual penalty)
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // If this is the last chance to fit an item in an existing bin, 
    // heavily reward it to avoid opening a new one prematurely
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening new bins: 
    // We scale the penalty based on progress to allow more flexibility early on 
    // and enforce consolidation as the stream concludes.
    if is_new_bin {
        score += 25.0 + (progress * 20.0);
    }

    // Lookahead interaction:
    // If the next item is large, penalize small post_residuals that leave 
    // too little space for a subsequent item.
    if next_item_size > 0 {
        let fit_next = post_residual as i32 - next_item_size as i32;
        if fit_next < 0 {
            // If current placement makes next item impossible, add a penalty
            score += 15.0 * (1.0 - progress);
        } else {
            // If it fits, reward the bin for maintaining a viable residual
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Dynamic adjustment based on mean_residual:
    // If open bins are generally empty, prefer filling them (lower score).
    // If open bins are already tight, avoid further fragmentation.
    let residual_pressure = (mean_residual - post_residual as f64) * 0.5;
    score += residual_pressure;

    // Criticality check:
    // If this is the only bin that can fit the item, aggressively lower its score
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, so it stays in the base score.

    // 2. Harmonic Class Logic:
    // We prioritize filling bins to specific "harmonic" thresholds (e.g., 50, 33, 25) 
    // to leave room for likely future items.
    let harmonic_penalty = if post_residual > 0 {
        let remainder = post_residual % 25;
        (remainder as f64).powf(1.5)
    } else {
        -50.0 // Huge bonus for perfect packing
    };
    score += harmonic_penalty;

    // 3. Lookahead Logic:
    // If next_item_size fits in the post_residual, drastically reduce the score.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Scarcity/Efficiency Logic:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // we should prioritize using it unless it's a very poor fit.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 30.0; // Discourage wasting the "last resort" bin on a bad fit
    }

    // 5. New Bin Threshold:
    // If it's a new bin (bin_residual == bin_capacity), set a threshold.
    // We only open a new bin if the current open bins result in "bad" fits.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are very full.
        score = 45.0 + (mean_residual * 0.5);
    }

    // 6. Progress Scaling:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the minimum possible item size (10)
    // are highly likely to be wasted. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Penalty for creating "dead space": gaps that cannot fit the next known item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Pressure: penalize opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Further penalize if there are bins that could have fit this item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Favor bins that bring the residual closer to the global mean (Best-Fit-like behavior).
        score += (post_residual as f64 - mean_residual).abs() * 0.5;

        // If this is the last fitting bin, prioritize it to avoid closing it prematurely
        // or leaving it as a stranded, nearly-full bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Progression scaling: as we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // We prioritize bins that result in a tight fit for the current item,
    // while penalizing placements that leave "fragmented" space (too small for common items).

    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize minimizing post_residual (already in score).
    // 2. Penalty for opening a new bin unnecessarily:
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 65.0; // Heavy penalty for opening new bin if existing ones fit
    }

    // 3. Lookahead optimization: 
    // If the post_residual is close to the next_item_size, reward this bin (perfect pairing).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.4;

        // If post_residual is too small for next_item, we penalize it slightly 
        // to encourage saving this bin for a smaller item later.
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 4. Global balance: 
    // If we have many open bins, penalize creating large residuals to consolidate.
    score += (open_bins_count as f64) * 0.5;

    // 5. Mean-residual alignment: 
    // Encourage bins to stay near the population average to maintain consistency.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 6. Final constraint: 
    // If this bin is the last chance for this item (fitting_bins_count == 1), 
    // drastically reduce score to force usage.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}
